window.STORY_DATA = {"stories":[{"id":"伍尔夫","name":"伍尔夫","source":"伍尔夫主线(2).docx","portrait":"人物图片/老年伍尔夫.png","subtitle":"旧日回声","accent":"#c6a878","scenes":[{"chapter":"序章","text":["《第八星系风云》","伍尔夫主线·旧日回声","【章节时间】","新星历前夕","【章节地点】","天使城要塞"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"序章","text":["【章节主题】","少年相遇、漫长守望、无法宣之于口的感情"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕：少年","text":["第一幕：少年"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情开始","text":["【剧情开始】","新星历前夕，天使城要塞还只是个破败的空间站。","金属墙壁上锈迹斑斑。","空气里弥漫着过滤系统勉强维生的铁腥味。","少年伍尔夫第一次见到林格尔，是在食堂的蒸汽管道旁。","男人正用一把改锥修理漏气的阀门。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"剧情开始","text":["袖口挽到肘部，露出结实的小臂。","侧脸上沾了油污，却浑然不觉。","“帮忙递一下扳手。”","林格尔头也不回地说。","伍尔夫愣了一秒。","才意识到对方是在跟自己说话。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情开始","text":["他慌忙从工具箱里翻出扳手递过去。","那天伍尔夫十四岁。","刚刚失去所有亲人。","像条流浪狗一样被收容进反抗军。","林格尔是第一个注意到他的人。","会把热汤多舀一勺倒进他的碗里。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情开始","text":["会在夜训后问他冷不冷。","会在他做噩梦惊醒时坐在床边。","什么也不说。","只是沉默地陪着。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["第二幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【剧情继续】","伍尔夫开始给林格尔写诗。","在训练日志的背面。","在机械图纸的空白处。","墨水总是洇开。","像那些他永远不敢说出口的字句。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["他把诗折成纸飞机。","从窗口扔出去。","看着它们飘进天使城要塞外围的真空里。","被宇宙射线分解成原子。","后来哈登发现了他的秘密。","那个书呆子推了推眼镜说："],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"剧情继续","text":["“你应该告诉他。”","“告诉他什么？”","伍尔夫反问。","“告诉他林格尔元帅的副官对他的‘过分依赖’已经变成了全要塞的笑话？”","“还是告诉他我每天晚上都在想他的嘴唇尝起来是什么味道？”","哈登沉默了。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["伍尔夫把所有的诗和画锁进一个金属匣子里。","埋在了天使城要塞地下三米处。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"剧情继续","text":["【玩家选择】","选择一：","【埋藏秘密】","剧情：","选择将所有情感隐藏，不让任何人知道自己的真实想法。","获得：","【隐忍值】","解锁：","伍尔夫隐藏档案线","选择二：","【向林格尔坦白】","剧情：","尝试向林格尔表达自己的感情，面对未知的未来。","获得：","【勇气值】","解锁：","少年时期特殊回忆"],"choices":[{"title":"埋藏秘密","key":"route_12_0"},{"title":"向林格尔坦白","key":"route_12_1"}],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["第三幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【剧情继续】","林格尔结婚那天。","哈登陪伍尔夫喝了一整夜的酒。","伍尔夫没有醉。","他的痛苦太清醒了。","像一把钝刀。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["一寸一寸地割着他的五脏六腑。","他站在要塞的瞭望台上。","看着林格尔和妻子的星舰飞向新居。","引擎的尾焰在真空里无声地燃烧。","像一场盛大而寂静的葬礼。","是他伍尔夫的葬礼。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"剧情继续","text":["后来是革命。","是战争。","是无数个不眠的夜晚","和堆积如山的尸体。","伍尔夫学会了把感情压缩成一个微小的芯片。","塞进大脑的最深处。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"剧情继续","text":["他成了林格尔最得力的副手。","成了所有人眼中坚不可摧的铁壁。","只有他自己知道。","夜深人静时。","他会调出军用记录仪里林格尔的影像。","那男人在战场上的侧脸。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"剧情继续","text":["被炮火映亮的眉骨。","通讯频道里那句永远听不厌的：","“伍尔夫，跟上我。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四幕","text":["第四幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情开始","text":["【剧情开始】","新星历元年。","林格尔战死。","伍尔夫在停尸房待了很久。","没有哭。","他只是用手指一遍遍地描摹林格尔眉骨的轮廓。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情开始","text":["像多年前隔着整个会议桌偷看时一样。","然后他站起来。","对等候在外的哈登说：","“把超级人工智能项目停了。”","哈登说：","“可是我们已经研究出眉目了。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情开始","text":["“停了。”","伍尔夫重复道。","那年冬天。","沃托下了第一场人工雪。","伍尔夫站在元帅府的窗边。","看着雪花坠落在庭院里的郁金香上。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"剧情开始","text":["那是林格尔生前最爱的花。","他忽然想起很多年前。","林格尔第一次教他开机甲时说的话：","“这世上没有什么能永远困住你，除非你自己选择留下来。”","伍尔夫在窗边站了一整夜。","雪停了。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"剧情开始","text":["花圃里的郁金香覆了一层薄冰。","像凝固在时光里的标本。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情开始","text":["【玩家选择】","选择一："],"choices":[{"title":"继续守护联盟","key":"route_25_0"}],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"继续守护联盟","text":["【继续守护联盟】","剧情：","接受林格尔留下的责任，成为新时代的守护者。","获得：","【责任值】","解锁："],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"继续守护联盟","text":["联盟元帅成长线","选择二：","【追寻旧日回忆】","剧情：","追寻林格尔留下的痕迹，寻找那些未曾说出口的话。","获得：","【羁绊值】","解锁：","林格尔隐藏回忆档案"],"choices":[{"title":"追寻旧日回忆","key":"route_27_0"}],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第五幕","text":["第五幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【剧情继续】","近三百年后。","当林静姝的芯片帝国染指八大星系时。","伍尔夫已经老得不太记得自己是谁了。","他的记忆像漏水的容器。","白天漏掉一些。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["夜里又会在噩梦里浮现。","唯一清晰的是林格尔。","总是林格尔。","那张脸在无数个版本的记忆里反复修剪。","到最后，伍尔夫已经分不清哪些是真实的。","哪些是他自己添上去的。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["他只知道。","一个在三百年前就该说出口的：","“我爱你。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕：人工智能的最后指令","text":["第三幕：人工智能的最后指令"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【剧情继续】","哈登问他：","“你是认真的吗？”","伍尔夫没有回答。","他在终端里输入最后一行代码：","核心指令——"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["在一切终结之后，自毁。","林格尔在生前的笔记里写过：","“无权限框架的人工智能，哪怕程序里写满了热爱人类，也终将成为人类的敌人。”","伍尔夫读到这句话时笑了。","他想。","那就让林格尔的预言成真吧。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["让那个英俊温柔的、不属于他的男人。","最后以这种方式。","和他一起终结这个疯狂的时代。","【隐藏剧情解锁条件】","达成条件：","① 完成【追寻旧日回忆】"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["② 伍尔夫羁绊值达到最高","③ 获得林格尔遗留档案","解锁：","【永恒回声】","隐藏剧情：","伍尔夫保存了一生的秘密。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["没有人知道。","那些埋在天使城要塞地下三米的金属匣子。","里面保存的不只是诗。","还有一个少年三百年前未曾说出口的答案。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第六幕","text":["第六幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情开始","text":["【剧情开始】","沃托暗杀时。","伍尔夫闻到了黑郁金香的香气。","意识消散之前。","他看见了林格尔。","还穿着那件沾满油污的旧衬衫。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"剧情开始","text":["还是那样侧着脸对他笑。","“来了？”","林格尔伸出手。","伍尔夫用尽最后一丝力气握住了那只手。","像一个十四岁的少年。","在天使城要塞的蒸汽管道旁。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"剧情开始","text":["终于接住了命运递来的扳手。","他的嘴唇翕动了一下。","没有发出声音。","——“跟上我。”","然后世界静了。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"终局剧情","text":["【终局剧情】","后来。","自由军团人工智能在玫瑰之心外围的信号塔里读取最后一组数据。","启动了自毁程序。","在程序自爆的最后一秒。","它模拟了伍尔夫的声音。"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"终局剧情","text":["三个字：","“收到了。”","【伍尔夫主线完成】","解锁称号：","「旧日守望者」","结局评价："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"终局剧情","text":["你守护了一生，却从未拥有。","你背负时代，却只想追上一道三百年前的身影。","有些人留下，是为了改变世界。","有些人留下，只为了等一句迟来的回应。","而伍尔夫的一生始于一句：","“帮忙递一下扳手。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"终局剧情","text":["终于一句：“收到了。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"}]},{"id":"图兰","name":"图兰","source":"图兰主线(2).docx","portrait":"人物图片/图兰.png","subtitle":"白银先锋","accent":"#d66b7d","scenes":[{"chapter":"序章","text":["《第八星系风云》","图兰主线","【章节时间】","新星历前后","【章节地点】","第五星系、白银要塞、第八星系"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"序章","text":["【章节主题】","无根之人、白银先锋、永远冲在最前方的刀锋"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["第一幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情开始","text":["【剧情开始】","图兰不知道自己从哪来的。","好像是","第五星系有家私人育婴中心搞活动。","新婚夫妻玩游戏赢免费培育资格，她就是那个奖品。","后来父母分手。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情开始","text":["育婴中心被取缔。","她被政府领走。","因为精神力突出被白银十卫挑走做了后备军。","她是最后一批后备军。","后来陆信将军建议白银十卫融入联盟。","再也不招了。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"剧情开始","text":["图兰成为了白银十卫最后一批留下的人。","她没有家庭。","没有过去。","甚至不知道自己真正来自哪里。","但她知道。","自己属于白银十卫。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["第二幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【剧情继续】","很多年过去。","图兰在白银第九卫当卫队长。","先锋突击。","专门干最不要命的活。","她嘴碎。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["穿得花里胡哨。","出去喝顿酒能骗三个人的感情。","投诉信堆了林静恒一抽屉。","林静恒对于这位在整个联盟各处都“美名远扬”的卫队长实在头疼。","剪过她“天牛须”。","禁过足。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"剧情继续","text":["但她下手最狠。","白银九永远是战场上第一个捅进去的刀。","她不靠谱。","可以胡闹。","可以让包括毒死人不偿命的林上将在内整个白银十卫头疼。","但只要战争开始。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"剧情继续","text":["她永远站在最危险的位置。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【玩家选择】","选择一：","【相信图兰的战场直觉】","剧情：","认可图兰看似混乱却极其精准的战斗判断，跟随白银九执行先锋突击任务。","获得：","【先锋值】","解锁：","白银第九卫战斗档案","选择二：","【约束图兰的冒险行为】","剧情：","尝试让图兰减少无意义伤亡，更重视自身安全。","获得：","【守护值】","解锁：","图兰隐藏心理线"],"choices":[{"title":"相信图兰的战场直觉","key":"route_11_0"},{"title":"约束图兰的冒险行为","key":"route_11_1"}],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第三幕","text":["第三幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【剧情继续】","白银要塞沦陷那天。","阿瑞斯·李逃出来。","图兰截住了他。","李上将在沃托的媒体上刚发完声明。","他说白银要塞失守是意外。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"剧情继续","text":["他将自己描述为力挽狂澜的英雄。","但图兰知道这个饭桶究竟干了什么。","图兰把他堵在天使城要塞外面。","三枚导弹。","把人打成渣。","然后才回林静恒复命。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"剧情继续","text":["“追究我的责任，我认罚。”","她说。","“但那姓李的王八蛋就是该死啊”","联盟崩溃。","白银要塞被轰炸。","她带着白银九在六七星系间打游击。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"剧情继续","text":["白银九是突击队。","不是后勤。","也不是运输。","但她路过第二星系的时候。","帮了一所逃难的大学。","几百个学生挤在破商船上。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["白银九卫接到情报说反乌会要封锁航道。","她掉头就把反乌会的补给站炸了。","保护普通人的安全。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四幕","text":["第四幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【剧情继续】","后来图兰弄了一批旧机甲。","东拼西凑","修修补补。","开到第八星系。","去找林静恒。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"剧情继续","text":["伍尔夫操纵的那场仗后。","林静恒失踪了十六年。","第八星系封闭。","内战。","物资见底。","空脑症军团组建。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["反导系统上马。","所有事情堆在一起。","图兰什么都得管。","除了陆必行，整个第八星系也就是她单着这些责任了。","她只是个先锋突击队的。","后勤也让她管。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["统筹也让她管。","忙得快被架在火上烧化了。","可她到底没撂挑子。","她从来不是最适合坐在指挥台后面的人。","但她知道。","总要有人留下。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["总要有人撑住白银十卫留下来的东西。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第五幕","text":["第五幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【剧情继续】","陆必行那会儿要去找失去消息的林静恒。","她只好把陆必行用麻醉放倒。","这是成了第八星系总长和卫队长心里再难拔出的一根刺。","扎了十几年。","后来直到林静恒回来。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["才拔出来。","林静恒从玫瑰之心回来时。","图兰把该说的不该说的都说了。","哭得不像个卫队长。","她不是不知道有情人再难相见的痛苦。","她也不是不知道那个失踪的人。"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"剧情继续","text":["是所有人心里无法放下的名字。","可是她知道有人必须留下。","有人必须活着。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第六幕","text":["第六幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情开始","text":["【剧情开始】","白银十卫重新聚齐的那天。","托马斯杨的声音从通讯频道里冒出来。","图兰愣了一下。","然后哭着骂：","“我操你弟，托马斯杨！”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情开始","text":["托马斯杨回答：","“啊？要操我弟啊，那行吧。”","十六年没见的兄弟。","晃如隔世。","图兰把军帽摔在地上。","骂完这个骂那个。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情开始","text":["最后。","她听见林静恒说：","“我也在。”","她捂着脸蹲下去。","半天没起来。","哭了。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第七幕","text":["第七幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【剧情继续】","图兰风流账多得数不清。","这位风流成性的奇女子","在战场上和情场上一刀切的贯彻她流氓而不要命的作风。","上了战场比谁都疯。","被导弹扫中跳生态舱那次。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"剧情继续","text":["差点交代在碎片堆里。","被捞上来的时候。","气还没喘匀。","第一句话是：","“我没问完呢——","统帅，你一个能听懂所有荤段子的男人，"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["到底怎么常年保持一副‘不与龌龊世俗同流合污’的姿态的？”","林静恒回答：","“不知道，可能是长得不像人妖？”","图兰笑出了眼泪。","她信自由宣言。","也信林静恒。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["她可以嘲笑所有人。","可以没个正形。","可以把战场当成自己的游乐场。","但她从未怀疑过。","白银十卫存在的意义。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第八幕","text":["第八幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【剧情继续】","“但是不瞒你说。”","她说。","“能服从命令、万事不用做主不担责任的感觉真是好。”","她当了一辈子兵。","被人捡过。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["被人嫌弃过。","被人信赖过。","也被时代推着走。","也不知道自己最终会去哪里。","但她知道。","自己属于白银十卫。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【玩家选择】","选择一："],"choices":[{"title":"继续成为先锋","key":"route_40_0"}],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"继续成为先锋","text":["【继续成为先锋】","剧情：","接受白银第九卫职责，在最危险的地方继续冲锋。","获得：","【白银信念】","解锁："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"继续成为先锋","text":["图兰战场记录","选择二：","【寻找自己的归处】","剧情：","回望自己的过去，寻找那个没有名字的孩子究竟是谁。","获得：","【自我认同】","解锁：","图兰身世隐藏档案"],"choices":[{"title":"寻找自己的归处","key":"route_42_0"}],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第九幕","text":["第九幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【剧情继续】","陆信将军的石像立在银河城广场上的时候。","图兰远远看过一眼。","她想。","如果陆信真的能开口说话。","大概会问她一句："],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"剧情继续","text":["“小姑娘，值吗？”","她大概会回一句：","“值啊将军。”","“我这一辈子，够本了。”","【图兰主线完成】","解锁称号："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["「白银先锋」","结局评价：","没有显赫的出身。","没有完整的过去。","但你用一生证明：","一个人的归处。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["从来不是出生的地方。","而是她愿意为之挥刀、为之守护的人。","她是白银九的第一把刀。","也是永远冲在最前面的那个人。","她不知道自己从哪里来。","但她知道自己为什么而战。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["“值啊将军。”","“我这一辈子，够本了。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"}]},{"id":"林静姝","name":"林静姝","source":"林静姝主线(1).docx","portrait":"人物图片/林静姝.png","subtitle":"玫瑰与荆棘","accent":"#c66092","scenes":[{"chapter":"序章","text":["《第八星系风云》","林静姝主线","“软弱是一种罪过”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一章 萌芽","text":["第一章 萌芽","【章节信息】","时间：林静姝幼年至成年初期","地点：沃托、白塔、天使城","主线人物：林静姝","章节关键词："],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第一章 萌芽","text":["失去、等待、执念、力量的萌芽。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["第一幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情开始","text":["【剧情开始】","林静姝记得那个下午，沃托罕见的阴天。","六岁生日刚过，管委会就派了人来。她在二楼走廊的窗户后面，看见楼下军靴锃亮的军官们排成一列，她哥哥被领出大门。那天出奇地安静，连院子里的智能草坪都忘了修剪。","林静恒上车前回头看了楼上一眼。","六岁的女孩就站在那扇窗后面，手紧紧地攥着窗帘，指甲掐进布料里，关节泛白。","她以为他会看见，会喊她下来，会像以前一样和她一起去那个被他们命名为“秘密基地”的阁楼角落里躲起来。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"剧情开始","text":["但他只是看了那扇窗户片刻，便转身上了车。","车门合上的瞬间，女孩终于带着她的独角兽追了出去，但她太小了，等她跑到门口时，车子已经升入空中轨道，加速成一道模糊的残影。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情开始","text":["【关键选择】","选择一：","【追上哥哥】","剧情倾向：","执念路线开启。","获得：","【执念值+10】","解锁：","「六岁那年的背影」","选择二：","【等待哥哥】","剧情倾向：","羁绊路线开启。","获得：","【亲情羁绊+10】","解锁：","「秘密基地回忆」","选择三：","【记住此刻】","剧情倾向：","观察路线开启。","获得：","【记忆值+10】","解锁：","「永不删除的影像」"],"choices":[{"title":"追上哥哥","key":"route_6_0"},{"title":"等待哥哥","key":"route_6_1"},{"title":"记住此刻","key":"route_6_2"}],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【剧情继续】","母亲劳拉·格登博士在那之后不久就“病逝”了。","父亲林蔚中将变得更沉默。","管委会又来了人，这次带走的是她。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["第二幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["【剧情节点】","地点：","白塔附属“青少年培养中心”","状态：","她被带进白塔附属的“青少年培养中心”。","那里没有窗，屋顶是永不暗下来的模拟日光。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"剧情节点","text":["他们检查她的身体，记录她的数据，给她注射各种各样的药剂。","一针舒缓剂的替代品推进她的静脉时，她听见旁边的研究员低声说：","“精神阈值超出均值七倍标准差，奇迹。可惜格登家那些废物检测不出来，还以为是个废物——好东西总是留给有心人的。”","从那天起，她学会了微笑。","【属性开启】","获得："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["【伪装值】","说明：","隐藏真实情绪。","学会观察人心。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["第三幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["【剧情节点】","时间：","林静恒离开后的第三年。","在林静恒离开后的第三年，她偷偷在黑市上弄到了一个简易的军用级信号接收器。","她记得哥哥说过，乌兰学院的定期通讯会经过一个特定的跃迁点中转。","她花了两个月破译了中转密钥——那只是个六位数的校园编码，林静恒写信时提过一次——"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["“学院内网密钥是270101，改密码的频率快赶上换制服了，烦。”","她收到了第一条关于他的信息，附了一张模糊的监控截图。","少年坐在图书馆角落里，校服扣子没扣好，眉头皱着在看什么，桌上摊着一本封面是机甲结构的书。","她把那张图片保存在个人终端最深的文件夹里，密码设成他离开那天的日期。","那是她往后几十年里无数个类似动作的第一次。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第四幕","text":["第四幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["【剧情节点】","时间：","进入管委会视野后的第七年。","进入管委会视野的第七年，她被允许参与白塔最外层的辅助工作。","表面上她是格登家听话的养女，学社会学的安静女孩，整天跟着那些贵妇们参加慈善茶会，为“反对将宠物抛尸太空”之类荒谬的议题站台。","但每个午夜，她会避开监控，潜入白塔边缘的数据整理室，把那些“已删除”的备份文件用暗码复制出来——这是劳拉留下的后手之一，哈登博士告诉她的。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"剧情节点","text":["她用了三年拼凑出“禁果”系统的轮廓。","伍尔夫元帅、哈登博士、管委会七位董事……","那些名字一个个亮起来，像暗夜里鬼火般的灯笼。","而她在名字的间隙里，看到了更多——","那些被精心掩盖的财务流向、域外海盗的物资输送记录、反乌会中部分派系与管委会的秘密联络。","这个世界是一盘棋。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["而棋盘上大多数人甚至不知道自己只是一枚卒子。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["【关键选择】","选择一："],"choices":[{"title":"继续调查真相","key":"route_19_0"}],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"继续调查真相","text":["【继续调查真相】","剧情：","深入追查白塔隐藏档案。","获得：","【调查值】","解锁："],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"继续调查真相","text":["「禁果系统资料线」","选择二：","【利用已有身份】","剧情：","隐藏锋芒，继续扮演格登家需要的女孩。","获得：","【伪装值】","解锁：","「格登夫人路线」","选择三：","【寻找改变棋盘的方法】","剧情：","开始思考如何掌握足够力量。","获得：","【权力值】","解锁：","「芯片研究前置线」"],"choices":[{"title":"利用已有身份","key":"route_21_0"},{"title":"寻找改变棋盘的方法","key":"route_21_1"}],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第五幕","text":["第五幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["【剧情节点】","时间：","十七岁。","十七岁那年，她偷偷做了一件事。","她在管委会的一次内部安全审查中，利用伪造的访问权限，删除了一个关键证人的全部电子档案。","那人原本要在听证会上指证格登家在伊甸园数据采集中的违规操作。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["听证会当天，证人“因病缺席”，三天后“因旧伤复发去世”。","格登家安然度过危机。","老格登第一次意味深长地看了她一眼，说：","“你比你母亲懂事。”","她低下头，做羞怯状。","指甲却掐进掌心。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第六幕","text":["第六幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["【剧情节点】","成年礼。","成年礼那天，她拿到两样东西：","一个“格登夫人预备役”的席位，","以及一份完整的“白塔早期芯片研究”资料。","哈登博士通过加密渠道留给她。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"剧情节点","text":["附了一句手写的话：","“静姝，力量本身无善恶，但使用力量的人必须有善的锚点。”","她把后半句删了。","只留下前半句。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["【关键选择】","选择一：","【相信哈登博士】","剧情：","保留完整留言。","获得：","【理性值】","解锁：","「力量边界」","选择二：","【相信自己】","剧情：","删除提醒，只留下力量本身。","获得：","【执念值】","解锁：","「禁果研究线」"],"choices":[{"title":"相信哈登博士","key":"route_28_0"},{"title":"相信自己","key":"route_28_1"}],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第七幕","text":["第七幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["【剧情节点】","时间：","成年后。","格登秘书长的求婚比她预想中来得早。","管委会需要巩固与格登家的联盟，","而格登家需要一个听话的传声筒。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"剧情节点","text":["她微笑着在婚约上签了字。","那天晚上打开个人终端，","给林静恒发了一条简短的消息：","“我要结婚了，哥哥。对方是管委会的人。”","消息显示了：","“已送达”。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["然后：","“已读”。","然后没有回复。","她等了三天。","删除了那条消息的历史记录。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第八幕","text":["第八幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["【剧情节点】","婚礼当天，她穿着一身白裙站在台上，旁边站着联盟最前途无量的男人。","台下无数双眼睛看着他们。","她微笑着让格登为她戴上面纱。","心里却在数——","她的个人终端里，"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"剧情节点","text":["那个被加密的文件夹里保存着七十三张林静恒在不同时期的影像。","最新一张，是他授衔少将时的官方肖像照。","年轻的将军军装笔挺，","目光冷淡地看向镜头外某处，","像是在看一个很远的地方。","那目光让她想起六岁生日那天，"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["他上车前回头看向窗户的那一眼。","婚后第二年，","她利用格登夫人的身份，","私自在天使城要塞郊外一个废弃的空间站里搭建了自己的第一间实验室。","启动资金来自于她在慈善基金中做账挪出来的款项——","每一笔都不超过一万星际币，"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"剧情节点","text":["分散在三百多个不同的项目里，","像沙漏中的细沙，","无声无息地流进她的掌心。","第一批生物芯片的实验对象，","是那些在战火中失去身份的流民。","没有人在意他们的去向。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["就像没有人在意尘埃落在哪里。","她改良了劳拉留下的原始芯片设计，","去掉了“进化”的冗余功能，","专注于“控制”。","如何用芯片建立一个自下而上的层级压制系统，","让每个携带者从骨子里服从更高级别的芯片持有者。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["“这是人性固有的弱点。”","她说。","“我只是把它写进了代码。”","第一代芯片的致死率是百分之七十三。","她不记得自己盯着那个数字看了多久。","最后她说："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["“数据记录下来，准备第二代。”","【路线锁定】","当前林静姝路线：","【禁果研究】","开启。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第九幕：玫瑰凋零之前","text":["第九幕：玫瑰凋零之前"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["【剧情节点】","时间：","林静恒“死亡”消息传回沃托。","在林静恒“死”于玫瑰之心的消息传到沃托的那天晚上，","她独自坐在书房里。","面前是那条关于："],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"剧情节点","text":["“白银要塞总指挥官遇刺，舰毁人亡”的新闻推送。","伊甸园的死亡判定记录她已经核实过——","确实消失了。","确实是已死亡状态。","她把那杯茶放下。","站起来走到窗前。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"剧情节点","text":["窗外沃托的夜雨被人工天气系统调控得恰到好处，","细密绵长，","像一首忧伤的夜曲。","“我要你偿命。”","她看着窗上模糊的倒影默默说","那是她最后一次允许自己露出真实的表情。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"剧情节点","text":["【剧情判定】","触发事件：","「哥哥死亡」","玩家选择：","【相信死亡】","剧情："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["接受林静恒死亡事实。","将所有情感转化为复仇目标。","获得：","【复仇值】","解锁：","「自由军团路线」"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["【拒绝相信】","剧情：","继续追查死亡记录。","寻找哥哥可能存在的痕迹。","获得：","【执念值】"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["解锁：","「兄妹羁绊隐藏线」"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第十幕","text":["第十幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情节点","text":["【剧情节点】","时间：","林静恒死亡后的三年。","后来她花了三年时间，","将自由军团的网络从域外边缘一点点渗透进联盟七大星系。","那些遍布各星系的芯片携带者，"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"剧情节点","text":["像隐秘的根系，在暗处生长。","直到有一天，","整片森林会同时开花，","露出狰狞的本来面目。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第十一幕","text":["第十一幕","【隐藏剧情】","她偶尔会在夜深人静时登陆那个废弃的邮箱。","查看早年林静恒发给她的那些消息。","大多是节日的例行问候。","最长的一条，"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第十一幕","text":["是她婚礼前：","“如果你不想嫁，我可以说服元帅出面。”","她当时回的是：","“不必了，哥哥，我很幸福。”","这句话后来被反乌会的某次数据截获中作为“证据”留存，","证明格登夫人对管委会忠心耿耿。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第十一幕","text":["林静姝记得那个下午。","她穿着那件白色连衣裙，","站在格登家的大厅里。","未婚夫在另一头和客人寒暄。","她的个人终端响了一下。","是林静恒的回复。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第十一幕","text":["“好。”","一个字。","她把它存进了那个加密文件夹里。","密码是她哥哥离开的那天。","她曾经只是想留住一个离开的人。","后来，她想留住一种不会失去任何人的未来。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第十一幕","text":["可是她忘了一件事。","如果一个未来需要所有人交出自己的选择，","那么被留下的人，","还算是真正活着吗？"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二章 花期","text":["第二章 花期","【章节信息】","时间：新星历后期，玫瑰之心决战阶段","地点：玫瑰之心天然虫洞、自由军团旗舰","主线人物：林静姝、林静恒","章节关键词："],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第二章 花期","text":["重逢、信念决裂、最后的守望、无法回头的花期。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕：玫瑰之心","text":["第一幕：玫瑰之心"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"剧情开始","text":["【剧情开始】","玫瑰之心的星空是暗的。","林静姝站在指挥舰的观景窗前，","看着远处人类联军的阵型在她的精神网攻击下开始撕裂。","自由军团的机甲像蜂群一样密集地涌向天然虫洞区，","而她的哥哥，在那艘指挥舰上。"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"剧情开始","text":["他们之间有十六年，二十光年，","有无数刀光剑影，","以及无法跨越的观念鸿沟。","“主人，第八星系增援到了。”","手下的声音从通讯器里传来。","她没回答。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情开始","text":["她忽然想起那一年的那个下午。","六岁的男孩在车开走前，","用口型对她说了两个字。","她那时没看清。","后来很多年里反复回忆，","她猜测是：“等我”。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情开始","text":["还是：“别哭”。","又或者，只是风划过车窗的错觉。","直到此刻。","她看着那个背影，","忽然意识到","那两个字也许并不重要。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情开始","text":["重要的是他确实说了什么。","而她确实相信过。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["第二幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【剧情继续】","“进攻。”","林静姝下达命令。","自由军团的机甲群如浪潮般涌向前方。","精神网攻击同时叠加上去。","联军阵型在瞬间出现裂口。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"剧情继续","text":["她看见林静恒的指挥舰被三架超级重甲同时锁定。","他紧急转向。","防护罩爆出刺目的白光。","她在通讯频道里听到了他的声音。","隔着十六年。","隔着无数谎言与真相。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"剧情继续","text":["他的声音依然带着她记忆里特有的冷淡和锐利。","“林静姝。”","他没有叫她妹妹。","“是我。”","她按住通讯键。","声音平稳得像在念一段演讲稿。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["“静恒，我们谈谈。”","指挥舰在她的精神网攻击范围边缘停了下来。","林静恒没有关通讯。","也没有回答。","沉默在真空里蔓延了漫长的一瞬。","像宇宙中一处即将坍缩的星云。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"剧情继续","text":["“你知道我在第八星系时为什么要救你吗？”","她说：","“不是因为愧疚，也不是因为还惦念着你。”","“我只是想知道，这个世界上是否还有一个人，不会在任何条件下选择抛弃我。”","“结果呢？”","他的声音隔着干扰波传来，"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["有些失真。","她停了一下。","然后笑起来：","“结果你确实不会抛弃我——”","“你宁可被整个世界碾碎也不肯弯腰。”","“你永远不会主动离开任何人。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["“你只会等着别人离开你。”","“所以我走的时候，你不会追上来。”","通讯频道里忽然响起轻微的电流声。","像一声被吞回去的叹息。","她没有等他回答","骨肉血亲在瞬息万变的战场上"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"剧情继续","text":["更是逃不开相互试探、针锋相对的局面。","切断通讯","她下达新的攻击指令","自由军团的机甲群开始收缩阵型。","精神网攻击的强度骤然提升到最高档。","她看见林静恒的指挥舰在炮火中改变航向。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"剧情继续","text":["穿过她的包围圈边缘。","他的操作依然精准到近乎冷酷。","像一台永不疲倦的机器。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["第三幕","玫瑰之心天然虫洞区域。","状态：","最终决战开启。","“主人，联军的反攻正在加强。”","手下的声音再次响起。"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第三幕","text":["“我们的左翼已被突破。”","林静姝没有回头。","她只是望着远处那片连接第八星系的天然虫洞。","那里有她从未真正踏足过的地方。","那里有林静恒选择守护的星空。","“收缩到虫洞入口。”"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第三幕","text":["她说。","“放出所有备用小机甲。”","自由军团的指挥舰开始向天然虫洞区移动。","那个通道连接着第八星系。","也许再过几分钟，","她就会穿过它。"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第四幕","text":["第四幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【剧情继续】","一枚导弹忽然从侧翼飞来。","精准地击中了指挥舰的武器库。","机身剧烈倾斜。","她被保护性气体裹住，","在半空中翻滚了几圈。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"剧情继续","text":["军用记录仪的画面在剧烈晃动中闪过一道光影。","林静恒的指挥舰。","不知何时突破了包围圈。","距离她不到三个标准机身位。","炮口锁定了她。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"关键节点","text":["【关键节点】","目标锁定：","林静姝旗舰。","攻击权限：","开启。","沉默的一秒。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"关键节点","text":["她看见了军用记录仪上他所在机甲的驾驶舱。","隔着无数层合金与玻璃。","隔着一个宇宙的距离。","她没有躲。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"关键节点","text":["【玩家选择】","选择一【等待开火】","效果：","获得：","【执念终点】","选择二【主动防御】","获得：","【求生最大化】","选择三【启动备用芯片系统】","获得："],"choices":[{"title":"等待开火","key":"route_83_0"},{"title":"主动防御","key":"route_83_1"},{"title":"启动备用芯片系统","key":"route_83_2"}],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"控制终局","text":["【控制终局】"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第五幕","text":["第五幕"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【剧情继续】","那枚导弹偏离了目标。","击中了指挥舰的尾部能源系统。","爆炸的冲击波将她推向更深处。","通讯频道里最后响起的是一声极短促的断响。","像一个人把到嘴边的话又咽了回去。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"剧情继续","text":["她闭上眼睛。","感觉到指挥舰在她身边散架。","【剧情判定】","林静姝最终状态：","根据玩家选择产生变化。","结局一："],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"剧情继续","text":["【玫瑰花期】","解锁条件：","执念值最高。","自由军团覆灭。","林静姝直到最后，也没有否认自己的选择。","她相信："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["如果所有人都不会失去选择，","那么所有痛苦都会消失。","她只是没有发现。","她想创造的天堂，","最终也成为了另一种牢笼。","关键词："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【控制】","【执念】","【无法回头】","结局二：","【未完成的故事】","解锁条件："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["兄妹羁绊最高。","玫瑰之心最后一刻。","林静姝关闭了芯片控制权限。","她没有真正放弃过去。","她只是终于承认：","那个站在窗后的六岁女孩，"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"剧情继续","text":["等的从来不是一个救世主。","她只是想等哥哥回来。","关键词：","【遗憾】","【等待】","【未说出口的原谅】"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["结局三：","【蔚蓝之海】","隐藏条件：","完成：","◆ 秘密基地记忆","◆ 七十三张影像"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["◆ 哈登博士资料","◆ 林静恒兄妹线","她没有成为真正意义上的胜利者。","也没有得到完整的救赎。","林静恒最终在意的，","不是自由军团的蚁后。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["而是那个六岁生日后，","站在窗边看着他离开的女孩。","那个女孩曾经拥有一只独角兽。","也曾经相信哥哥一定会回来。","关键词：","【记忆】"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【失去】","【最后的温柔】"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第六幕：结局","text":["第六幕：结局"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"剧情继续","text":["【剧情继续】","后来，","自由军团蚁后的军舰在玫瑰之心的星空中，","被流弹击中。","炸成一朵熄灭的烟花。","当年林静姝星舰里的信号记录仪只存下最后一行乱码。"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"剧情继续","text":["像一个被匆匆切断的念头：","“如果当时我追上了那辆车——”","再往下是空白。","沃托历那年的雨季格外漫长。","而今时今日的天空正晴。","晴空万里。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"}]},{"id":"林静恒","name":"林静恒","source":"林静恒主线(9).docx","portrait":"人物图片/林静恒.jpg","subtitle":"白银孤刃","accent":"#75b7d7","scenes":[{"chapter":"序章","text":["林静恒主线第一章"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一章：","text":["第一章：","《白银要塞最后的灯火》","时间：","新星历270年。","地点：","白银要塞。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第一章：","text":["视角：","林静恒。","【章节开场】","新星历270年。","白银要塞。","联盟最坚固的防线。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第一章：","text":["这里曾经挡住过无数威胁联盟的危险。","无数士兵在这里出生入死。","有的永远留在了这片冰冷的宇宙。","而此刻。","白银要塞接收到一个特殊紧急传唤。","【联盟命令】"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第一章：","text":["沃托传来的命令摆在桌面上。","联盟要求林静恒返回。","接受质询。","【剧情】","林静恒看着那份命令。","作为联盟上将。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第一章：","text":["他知道服从命令意味着什么。","然而林当年腥风血雨，誉毁参半高调入主白银要塞","在城府算计和手段上不输管委会的老狐狸。","他知道。","这个命令，背后的水比想象的深。","【关键剧情】"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第一章：","text":["于是，","新星历270年，3月6日","林静恒悍然抗命。","【剧情展开】","他曾经是联盟最年轻的上将。","也是最锋利的一把利刃。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第一章：","text":["可是现在。","这把利刃选择了不按照命令挥下。","洛德站在指挥室里。","作为林静恒的亲卫。","他清楚自己的长官从来不是一个冲动的人。","每一次决定背后。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一章：","text":["都有他必须承担的理由。","通讯频道里。","林的妹夫格登试图劝说。","希望林静恒退一步。","希望他接受安排。","可是林静恒不会改变他决定。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一章：","text":["【玩家选择】","选择一：","「接受联盟调查」","剧情：","你选择暂时接受联盟安排。","因为你知道。","如果想改变一个庞大的体系。","必须先进入它。","观察它。","找到真正的问题。","属性：","战略 +10","联盟关系 +10","选择二：","「坚持调查真相」","剧情：","你没有妥协。","白银要塞不是政治斗争的工具。","这里守护的是无数人的生命。","在真相出现之前。","你不会离开。","属性：","战略 +15","战斗 +5","选择三：","「优先保护身边的人」","剧情：","战争和政治最大的区别。","是政治可以重新开始。","但生命不能。","你开始安排人员撤离。","确保最重要的人能够活下来。","属性：","外交 +10","白银要塞关系 +10","湛卢——联盟十大名剑，顶级人工智能","此刻正安静地执行着预定程序。","它知道。","这一刻不是意外。","而是主人提前安排好的另一条路。","作为陪伴林静恒多年的人工智能。","湛卢比任何人都清楚。","林静恒不会轻易把自己置于无法控制的局面。","包括死亡。","“湛卢。”","“执行计划。”","林静恒的声音依旧平静。","没有犹豫。","“遵命。”","人工智能没有询问原因。","因为它知道。","这个决定并不是临时起意。","从很久之前。","主人已经开始计算所有可能。","静渊号陷入攻击范围。","警报响起。","爆炸和混乱覆盖了整个航道。","联盟所有监测系统。","都记录下了同一个结果。","——"],"choices":[{"title":"选择一","key":"route_9_0"},{"title":"选择二","key":"route_9_1"},{"title":"选择三","key":"route_9_2"}],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第一章：","text":["林静恒死亡。","可是宇宙另一端。","一个没有被任何系统记录的位置。","林静恒完成了最后一步计划。","他没有逃离。","也没有仓促求生。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一章：","text":["只是按照早已计算好的方案。","走入生态舱，开始休眠。","他舍弃了联盟上将这个身份。","舍弃了白银要塞的荣耀。","从这一刻开始。","林静恒不再是联盟众人眼中的那个名字。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第一章：","text":["至少。","在很长一段时间里。","不是。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二章：","text":["第二章：","《漂流在星海的人》","时间","新星历270年后。","地点","第八星系。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二章：","text":["主要人物","陆必行","林静恒","独眼鹰（背景出现）","湛卢（隐藏）"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["【章节开始】","第八星系。","这里距离联盟中心很远。","没有沃托的政治中心。","也没有白银要塞曾经的辉煌。","这里有自己的规则。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"章节开始","text":["资源。","交易。","势力。","以及无数想在星海里寻找未来的人。","陆必行驾驶着自己的机甲。","穿行在第八星系边缘。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"章节开始","text":["这台机甲不是联盟军方制造。","也不是任何军火商提供的成品。","它来自陆必行自己的设计。","从能源系统到控制程序。","都是他一点点研究出来的成果。","在第八星系。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"章节开始","text":["独眼鹰是一个呼风唤雨的人物。","老军火贩子控制着大量资源和交易渠道。","也是陆必行成长过程中最重要的人。","独眼鹰把陆必行养大。","教会他如何在第八星系生存。","教会他面对危险。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["也教会他这个地方真正的规则。","只是。","他们对于未来的看法并不相同。","独眼鹰：","“小兔崽子”","“不是所有问题，都能靠知识解决。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["陆必行：","“可是如果没人相信知识。”","“那这个地方永远不会改变。”","一个是现实世界里摸爬滚打的人。","一个是始终相信未来的人。","一次独自探索中。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["陆必行驾驶机甲离开既定航线。","进入一片无人区域。","雷达突然捕捉到异常信号。","不是通讯。","不是能源波动。","而是一组微弱的生命维持数据。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"章节开始","text":["【选择】","选择一：","「靠近信号源」","陆必行改变航向。","未知区域意味着危险。","但是。","如果那里真的还有一个活着的人。","那么放弃，就意味着死亡。","属性：","文明值+10","选择二：","「分析生态舱数据」","陆必行没有立即靠近。","他开启扫描系统。","分析生态舱结构。","确认能源状态。","寻找最安全的救援方式。","属性：","科研值+10","选择三：","「返回基地寻找支援」","未知的危险无法预测。","陆必行知道。","一次错误的决定。","可能让救援变成新的事故。","属性：","战略值+5","最终。","陆必行还是回到了那个信号的位置。","因为他始终无法忽视一个事实。","那里。","可能还有一个人在等待。","漂浮在宇宙中的生态舱已经损坏。","外部装甲留下长期漂流的痕迹。","内部系统却仍然维持着最低运行状态。","陆必行打开扫描。","发现里面有一个生命体征。","很微弱。","但存在。","他开始检查生态舱。","能源接口。","生命维持系统。","休眠程序。","每一步都必须谨慎。","因为里面的人已经沉睡太久。","任何错误操作。","都可能造成无法挽回的结果。","一天过去。","生态舱没有任何变化。","两天过去。","里面的人依旧沉睡。","陆必行没有离开。","他继续修复设备。","继续观察生命数据。","等待那个不知道名字的人醒来。","他不知道。","这个人曾经是谁。","不知道这个人经历过什么。","更不知道。","这个沉睡的人。"],"choices":[{"title":"选择一","key":"route_22_0"},{"title":"选择二","key":"route_22_1"},{"title":"选择三","key":"route_22_2"}],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["曾经站在联盟最高的位置。","很久以后。","生态舱终于出现变化。","生命维持系统重新调整。","沉睡状态解除。","那个在星海中漂流许久的人。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"章节开始","text":["终于睁开眼睛。","陌生环境。","陌生设备。","陌生的人。","林静恒醒来的第一时间。","不是询问过去。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["而是判断现在。","位置。","危险。","身份。","所有信息在极短时间内重新整理。","陆必行："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["“你醒了。”","“我叫陆必行。”","林静恒：","“这里是什么地方？”","陆必行：","“第八星系。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["生态舱内部。","一个沉默许久的人工智能程序重新启动。","但是。","它没有向陌生人介绍自己。","它只是安静等待。","等待自己的主人重新回到这个世界。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["【章节结尾】","林静恒看着眼前这个年轻人。","他不知道对方是谁。","也不知道自己沉睡了多久。","但是。","有一点已经确定。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["他的计划之外。","出现了一个新的变量。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二章结束","text":["第二章结束","解锁：","【生态舱档案】","【陆必行初遇】","【未知身份】"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三章《芯片迷雾》","text":["第三章《芯片迷雾》","开场","第八星系。","很多事情表面上看起来正常。","“日可云车”依旧运行。","城市依旧繁忙。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三章《芯片迷雾》","text":["人们依旧相信自己生活在熟悉的世界里。","可是有些东西，已经悄悄改变。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["第一幕","黄静姝坐在颠簸不平的车上。","她靠着座椅，很不耐烦。","周围的人太吵。","这个地方太挤。","她只想早点回去。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["然后。","她听见了哭声。","一个孩子。","正在哭。","声音很近。","近得像就在车厢里面。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["黄静姝皱眉。","“吵死了。”","她本来只是觉得烦。","可是很快。","她发现了一件奇怪的事。","整辆车上。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["没有一个人回头。","没有人安慰孩子。","没有人询问发生了什么。","甚至没有人表现出听见哭声。","黄静姝脸色变了。","她知道自己患有空脑症。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["她知道自己的感知方式和别人不同。","但她同样知道。","这一次。","不是自己的错觉。","选择：","选择一："],"choices":[{"title":"继续寻找声音来源","key":"route_37_0"}],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"继续寻找声音来源","text":["【继续寻找声音来源】","结果：","黄静姝顺着哭声寻找。","她发现一个孩子被隐藏在人群之中。","有人正在带走他。","属性："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"继续寻找声音来源","text":["文明+10","选择二：","【直接阻止可疑人员】","结果：","黄静姝没有耐心慢慢观察。","她直接冲了过去。","对方还没有反应过来。","手里的东西已经飞了出去。","属性：","战斗+10","选择三：","【记录异常，寻找证据】","结果：","黄静姝强迫自己冷静。","她开始记录看到的一切。","因为她知道。","有人正在利用某种方式欺骗人群。","属性：","战略+10"],"choices":[{"title":"直接阻止可疑人员","key":"route_39_0"},{"title":"记录异常，寻找证据","key":"route_39_1"}],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["第二幕","事情结束之后。","黄静姝发现。","那些人并不是普通绑匪。","他们利用一种特殊芯片。","影响人的感知。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["让所有人看到他们希望别人看到的东西。","真实发生的事情。","被隐藏了。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["第三幕","这件事最终进入了黑洞的调查范围。","佩妮整理完资料。","把结果交给四哥。","“四哥。”","“这个东西，不太像普通犯罪。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["林静恒：","“哪里不普通？”","佩妮：","“它改变的不是人的行动。”","“是人的认知。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四幕","text":["第四幕","湛卢重新检查芯片数据。","沉默片刻后。","人工智能给出了判断。","湛卢：","“主人。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四幕","text":["“检测到与禁果系统相关的数据痕迹。”","林静恒停了一下。","禁果。","这个名字。","意味着太多过去。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第五幕","text":["第五幕","调查继续深入。","所有线索。","最终指向一个名字。","蜘蛛。","没有人知道他的真实身份。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第五幕","text":["只知道。","芯片。","幻觉。","失踪儿童。","都和这个名字有关。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第六幕","text":["第六幕","线索指向第八星系地下世界。","破酒馆。","这里藏着各种交易。","消息。","秘密。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第六幕","text":["以及不愿被联盟看到的人。","而蜘蛛。","就在这张隐藏的网络之中。","章节结束：","林静恒看着手中的资料。","芯片只是表面。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第六幕","text":["真正隐藏在背后的东西。","才是湛卢警告他的原因。","沉睡多年之后。","旧时代留下的影子。","终于重新出现。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三章结束","text":["第三章结束"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["第四章：毒巢鸿门宴","【章节开场：鸦片芯片】","蜘蛛被抓获之后。","那枚藏在人体内的鸦片生物芯片，被湛卢从他的身体中完整取出。","它安静地躺在实验台上。","只有指甲大小。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["却隐藏着能够改变无数人命运的危险。","破酒馆内。","陆必行连续数日没有离开分析设备。","星海学院的实验条件并不算完善。","但这位年轻校长依然凭借惊人的技术能力，一层层拆解芯片结构。","从神经接口。"],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["到意识诱导。","再到生物强化模块。","越来越多的数据被还原。","陆必行看着投影中的复杂结构，脸上的轻松逐渐消失。","陆必行：","“这不是普通的幻觉芯片。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["他调整数据模型。","陆必行：","“它能够影响人的感官。”","“甚至可以让大量目标同时产生错误认知。”","“更麻烦的是……”","他指向其中一段代码。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["陆必行：","“这里有伊甸园技术的痕迹。”","“有人拿到了部分底层逻辑。”","“但是他们没有保留原本的限制。”","林静恒站在一旁。","安静听完。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["他看着屏幕上的数据。","林静恒：","“所以。”","“这不是一个小组织能完成的东西。”","陆必行点头。","陆必行："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“至少背后有人掌握完整技术链。”","湛卢同步完成分析。","湛卢：","“先生。”","“芯片解析结果确认。”","“该装置具备感知干扰、意识诱导以及人体机能强化功能。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“技术来源与联盟早期伊甸园相关技术存在关联。”","“但属于不完整改造版本。”","林静恒低头看着那枚芯片。","林静恒：","“不完整。”","“说明他们还在继续实验。”"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["湛卢：","“是。”","林静恒：","“继续查。”","“不要停留在芯片本身。”","“找到制造它的人。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["几天后。","一封加密通讯抵达黑洞。","发送方：","毒巢。","内容：","邀请第八星系所有地下势力代表，前往边缘废弃空间站参加会面。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["没有商量。","没有拒绝选项。","这是一场强制性的邀请。","湛卢读取完信息。","湛卢：","“先生。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“毒巢同时向多个第八星系地下势力发送邀请。”","“其中包括黑洞。”","“目标地点为废弃改造空间站。”","“空间站长期脱离联盟监管。”","“内部情况未知。”","林静恒看着邀请函。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["没有马上回答。","湛卢：“先生”","“根据现有信息。”","“此次行动存在高风险。”","“对方选择主动暴露位置。”","“目的值得分析。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["林静恒：","“他们不是想隐藏。”","湛卢：","“先生？”","林静恒：","“如果只是处理蜘蛛留下的问题。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“不需要召集整个第八星系地下势力。”","“他们想让所有被邀请的人看到结果。”","湛卢：","“所以先生认为，拒绝邀请会损失关键信息。”","林静恒：","“蜘蛛只是入口。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“真正的问题在后面。”","湛卢展开空间站资料。","废弃空间站。","能源系统未知。","防御系统未知。","内部人员未知。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["湛卢：","“先生。”","“是否需要绕开会面地点，进行远程调查？”","林静恒：","“他们既然邀请我们。”","“就一定准备好了防止远程观察的方法。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“距离越远，信息越少。”","湛卢：","“明白。”","“进入空间站前，我会建立隐蔽通讯节点。”","“确保撤离路线。”","林静恒："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“可以。”","“不要主动接触他们的系统。”","“先看他们想干什么。”","湛卢：","“明白。”","【选择交互界面】"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["选择一：【暂缓赴约，继续调查】","剧情：","你选择暂时不进入毒巢空间站。","虽然降低了直接进入敌方环境的风险，但也失去了近距离确认幕后势力的机会。","属性：","战略值+5","隐藏影响：","毒巢后续行动提前展开。","选择二：【接受毒巢邀请，前往空间站】","剧情：","明知这是一场危险未知的会面，仍然选择进入对方安排好的地点。","因为只有进入敌人的舞台，才能知道他们真正想展示什么。","属性：","战略值+10","解锁：","毒巢空间站主线。","选择三：【让湛卢提前建立监听节点】","剧情：","进入空间站之前，让湛卢建立隐蔽数据通道。","不主动暴露行动，同时保留撤离与调查能力。","属性：","科研值+10","（主线选择二）","第八星系边缘。","一座废弃空间站漂浮在深空之中。","它曾经属于联盟军用体系。","如今却成为无人管理的灰色区域。","林静恒独自进入。","身边只有湛卢。","没有军队。","没有公开身份。","没有任何多余力量。","这正符合黑洞四哥的身份。","空间站入口处。","毒巢人员已经等待多时。","林静恒没有理会。","湛卢同步扫描。","湛卢：","“先生。”","“空间站内部存在多个高权限区域。”","“部分区域无法扫描。”","“推测存在特殊隔离设施。”","林静恒：","“记录。”","“不要提前暴露。”","湛卢：","“明白。”","进入贵宾区域。","这里已经聚集了来自第八星系各处的地下势力代表。","所有人脸色都不好看。","因为他们都知道。","自己不是来参加会议。","而是被强行带来的。","就在这时。","一个熟悉的声音从人群中传来。","“林。”","林静恒停下脚步。","人群后方。","独眼鹰站在那里。","第八星系最大的军火商之一。"],"choices":[{"title":"暂缓赴约，继续调查","key":"route_71_0"},{"title":"接受毒巢邀请，前往空间站","key":"route_71_1"},{"title":"让湛卢提前建立监听节点","key":"route_71_2"}],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["陆必行的养父。","也是当年旧事中的重要人物。","独眼鹰看着他。","“我还以为，你这种人死了，大家都能少点麻烦。”","林静恒看向他。","“看来你的愿望没有实现。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["独眼鹰冷哼。","“你倒是一点没变。”","林静恒：","“嗯，时间改变不了什么”","“某些人几百年了脑子还没发育完全”","独眼鹰："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“至少我还能看出来，谁活着会惹麻烦。”","林静恒：","“那你应该先看看自己。”","“毕竟你现在也在这里。”","两人多年冤家路窄积累的旧怨。","在这一刻碰撞出了些许火星撞地球的意味。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["但还没来得及继续。","大厅中央。","灯光突然暗下。","所有人的目光转向高台。","有人来了。","一个身影缓缓走出。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["零零一。","第二部分：","毒巢空间站中央实验大厅浸在惨白冷光里，阶梯看台挤满第八星系各方地下势力，人人噤若寒蝉。高台中央站着零零一，半边躯体替换成冰冷金属，缝合血肉的痕迹狰狞外露，脸上却挂着一层温吞虚伪的笑意，骨子里是浸透骨髓的偏执狂热。","半空巨型全息投影骤然亮起，密密麻麻的人体改造图谱、心脏植入生物芯片数据流铺满视野。零零一语调平缓，裹着一层蛊惑人心的绵软：","“联盟用伊甸园锁住人类两百年，我们不必再枯等自然演化，造神计划能亲手重塑血肉凡胎，人人皆可超脱凡俗桎梏。”","投影切换，两段残酷活体实验影像同步播放。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["普通人植入芯片后肉身暴涨、皮肉硬化，枪炮轰击只能凹陷，可一旦芯片能源耗尽，人体便会急速干瘪、腐烂成一滩碎肉。","看台下众人看得头皮发麻，细碎的倒抽冷气声此起彼伏。","看台阴影里，林静恒斜倚金属栏杆，周身气息淡得几乎融进暗处，湛卢化作机械手依附在他小臂，同步推送全站扫描数据。","湛卢：","“先生，芯片与蜘蛛体内样本完全同源，代号造神计划，可强化躯体、屏蔽常规热武器，同时强制篡改所有生物感官，成瘾性极强。”","林静恒指尖漫不经心地轻叩栏杆，声音压得极低，听不出半点情绪起伏："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“全部实验数据完整留存，不要遗漏分毫。”","身侧独眼鹰攥紧拳头，鸳鸯眼钉在腐烂的实验体影像上，胸腔里的怒火中烧，压低嗓音：","“拿活人当耗材肆意折腾，这群东西根本称不上人。”","林静恒淡淡侧目，灰色眼底覆着一层薄霜：","“从古至今，自认手握真理的疯子，从来不会承认自己疯癫。”","独眼鹰嗤笑一声，半点不加掩饰地扬声讥讽："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“什么进化宏图，说穿了不过是刨开活人皮肉造恶鬼，顶多叫见鬼计划！”","话音落地，全场瞬间死寂，数十道目光齐刷刷扎向二人。","零零一脸上浅笑分毫未变，眼底却淬满刺骨寒意，轻飘飘一句回敬：","“眼界狭隘的守旧者，永远看不懂文明新生的变革。”","同步副线","北京β星星海学院机甲存放室，怀特凭着偷学破解加密锁，死拉硬拽薄荷、黄静姝、斗鸡维塔斯，非要开教学机甲上天兜风。"],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["怀特眉飞色舞，满脑子只有胡闹，半点不知轻重：","“就低空溜一圈，绝不离开大气层，完事咱们悄无声息溜回来，校长绝对查不到半点痕迹！”","薄荷冷眼斜睨他，早看透这人做事毫无分寸：","“上次私改教学设备、弄坏传感器，你才刚被罚打扫机房一周，转头就忘？真出纰漏谁来兜底？”","黄静姝皱紧眉头，空脑症对异常磁场天生敏感，心底一阵发慌：","“这台机甲是人贩子蜘蛛遗留机型，系统锁死了陌生跃迁航线，贸然启动太凶险。”"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["斗鸡天生惧怕机甲精神网冲击，上次初次链接直接震到脑震荡，缩着身子往后躲：","“我不想上去，万一失控根本没有应对办法。”","怀特不耐烦地一把推搡斗鸡，蛮横拽住几人往舱里拖：","“少扫兴，一群胆小鬼，机会摆在眼前都不敢见识世面！”","几人争执拉扯间，机甲预设跃迁程序不受控制自行激活，舱门瞬间落锁，操控权限彻底脱离几人掌控，只能眼睁睁看着机身自动升空，朝着毒巢空间站坐标跃迁而去。","学院实验室里，陆必行调取机甲后台航行记录，看清目的地那一刻，脸上温和笑意瞬间褪得干干净净。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["他办学收留第八星系各色底层孩子，哪怕是一身痞气的少年，也总耐着性子循循善诱，可眼下四个学生闯下足以丧命的弥天大祸，心底积攒的火气再也压不住。","他没有半分迟疑，取出从蜘蛛身上缴获的同款造神芯片植入胸腔，芯片铺开大范围伪装场，所有监控、扫描设备都会将他识别成林静恒。","陆必行抬手对着镜面理了一身深色长款外套，望着那张不属于自己的冷冽眉眼，又急又无奈，像往常训学生那样在心里盘算好全套惩戒：","四个混小子，等平安带回，论文周直接加量翻倍，机甲库房打扫一个月，每日两小时体能特训，星际安全论述三篇，半分情面都不留。","来不及多耽搁，他驾驶小型备用飞行器，循着跃迁轨迹全速追赶毒巢空间站。","陆必行向来胆大敢闯，机甲、芯片、加密系统样样精通，哪怕孤身闯入敌窝，也不会露半分怯意。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["停机区双线交汇","毒巢空间站停机轨道覆着一层薄霜，空旷死寂，冰冷金属泛着肃杀寒光。","林静听完湛卢推送的异常航行信号，得知一台归属星海学院的机甲闯入站内，当即动身前往停机区，独眼鹰紧随其后，湛卢恢复人形跟在二人身侧，实时同步四周安保布局。","湛卢：","“停机区全部安保机器人进入警戒状态，目标机甲为蜘蛛遗留制式，驾驶员是陆校长名下四名未成年学生。”","林静恒步伐平稳，神色冷淡无波："],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“过去查看，不要打草惊蛇。”","轨道尽头。","肇事机甲平稳停靠。","舱门缓缓滑开。","四个少年跌跌撞撞走出来。","怀特还在嘴硬逞强，刚落地就被空间站刺骨寒气冻得缩起脖子。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["没等几人摸清周遭环境。","飞行器舱门打开。","一道身形走下。","眉眼、身形，全是林静恒的模样。","正是靠芯片伪装的陆必行。","怀特一眼没分辨出真假，反倒凑上去讨好："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“四哥？没想到能在这碰见您！”","陆必行卸下平日里温和校长的假面。","周身气场骤然沉冷。","训人时的严肃劲儿，竟与林静恒有几分相似。","四个少年齐齐一僵。","连大气都不敢出。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["他先盯住挑事的怀特。","陆必行语气没有半分纵容：","“私闯机甲存放室、破解加密锁，上次弄坏教学仪器罚你打扫机房，看来是半点没长记性。”","“偷开作战机甲闯入敌对空间站，拿四条人命赌一时好奇。”","“每日两小时体能加练，机甲库房清扫三十天，三篇五千字星际安全论文。”","“不许代写，我逐字逐句核对。”"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["怀特瞬间耷拉下脑袋。","肩膀垮得抬不起来。","半句辩解都不敢往外说。","陆必行转头看向斗鸡。","少年本就畏惧精神网。","课堂上反复宣讲的风险，全然没有真正放在心上。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["陆必行依旧没有心软：","“课堂反复讲机甲精神网初次链接会重创普通人神经。”","“你左耳进右耳出。”","“后续所有机甲模拟训练单独加练，直到基础匹配达标才能休息。”","薄荷自知没能拦住同伴。","依旧逃不开责罚。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["陆必行语气稍缓，却依旧条理分明：","“明知航线异常却没能强行制止。”","“每日一小时机械理论加练。”","“全年教学器材档案全部由你整理归档。”","最后。","轮到孤僻的黄静姝。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["陆必行看着这个患有空脑症的孩子。","他从来是个和稀泥的性子，希望他好我好人人都好。","况且对八星系的孩子他心里始终有一份特殊的照顾。","但此刻。","他也不会一味纵容。","陆必行："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“你天生能提前感知异常，却选择旁观不作为。”","“本周所有晚自习留校补习航行基础。”","“全套安全考核合格才算结束。”","怀特憋了半天。","小声嘟囔：","“我们就是单纯好奇，没想惹事。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["陆必行眉峰一挑。","语调沉了几分。","声音里藏着陆校长独有的鸡汤风味：","“好奇就能拿性命开玩笑？”","“这里是实验基地。”","“落在他们手里，你们知道啥结果吗。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“到时候再后悔，来得及吗？”","少年们垂头丧气。","往日胡闹的气焰消散得一干二净。","就在这时。","轨道另一端传来平缓脚步声。","真正的林静恒带着湛卢、独眼鹰缓步走来。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["灰色双眼直直望向顶着自己面孔的陆必行。","陆必行尴尬的摸了摸鼻子","身上伪装幻象瞬间消散。","清秀眉眼恢复原样。","场面一时尴尬至极。","独眼鹰震惊地扫了眼自家儿子。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["又瞥了一排蔫头耷脑的少年。","掩饰尴尬似的嗤笑几声：","“管教这群皮猴子，你训人的架势跟操练新兵似的，也真有耐心。”","陆必行咽了咽口水，","不知道说什么只好继续压榨四个倒霉学生。","语气是陆校长一贯软硬兼顾的模样："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“等回到飞行器，所有处罚立刻生效。”","“一个月内禁止接触任何机甲设备。”","四个少年鹌鹑似的老老实实站成一排。","彻底安分下来。","（第四章：毒巢鸿门宴 第二部分·完）","明白，下面直接输出修正版完整第三部分。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["第三部分","毒巢空间站停机轨道一片寂静。","蜘蛛遗留机甲停靠的位置，还残留着跃迁发动后的灼烧痕迹，金属外壳因为高温微微变形。","空气中，一层极淡的能量波动尚未消散。","那是两枚同源生物芯片互相干扰后留下的痕迹。","陆必行站在机甲旁，原本覆盖在身体表面的伪装场正在逐渐失效。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["属于林静恒的冷峻轮廓像一层被水冲淡的影像，从他的眉眼、身形上一点点剥离。","最后留下的，是那个年轻、温和，却总带着一点不合时宜的理想主义气质的陆校长。","湛卢从林静恒腕侧展开。","机械结构缓缓重组，人形机甲站立在冷光之中。","碧绿色光学眼扫描过陆必行胸口尚未完全闭合的芯片植入位置。","“先生。”"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["湛卢平静开口。","“检测完成。”","“陆先生体内植入芯片，与蜘蛛体内提取出的造神计划生物芯片属于同源技术。”","“该芯片能够制造大范围感官伪装场，影响人工智能识别系统，并模拟目标人物基础外部特征。”","“但权限有限，不具备接入伊甸园核心网络能力。”","陆必行低头看了一眼自己的胸口。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["然后很认真地评价：","“从技术角度来说，它确实有点意思。”","他说着，忍不住又补充了一句：","“至少刚才那么多安保设备，没有一个第一时间发现我是假的。”","独眼鹰站在旁边，脸色越来越难看。","“你还有心思研究它？”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["陆必行抬头。","独眼鹰盯着他：","“你顶着林静恒的脸往这种地方闯。”","“这里是什么地方，你不知道？”","“这里的人刚才如果多看一眼，直接开火，你现在还能站在这里分析芯片优缺点？”","陆必行摸了摸鼻子。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“老陆别急，我计算过风险。”","独眼鹰冷笑：","“你计算过？”","“你计算的结果就是带着三个未成年学生和自己一起闯进敌人的实验基地？”","陆必行沉默了一下。","“……四个。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["独眼鹰额角一跳。","“重点是这个吗？”","陆必行终于不说话了。","林静恒站在一旁，从头到尾没有插话。","直到两人的争执结束，他才淡淡开口：","“伪装技术不错。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["陆必行下意识看向他。","林静恒继续：","“漏洞明显。”","陆必行：“……”","独眼鹰难得找到机会，又嗤笑一声。","“听见没有？”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["陆必行无奈：","“我至少成功进来了。”","林静恒看了他一眼。","“运气也是计划的一部分？”","陆必行顿时安静。","独眼鹰憋了一下，没忍住笑了一声。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["多年过去。","林静恒这张嘴，果然还是一样毒。","林静恒没有继续纠缠。","他的目光越过停机区，落向空间站更深处。","那里有一片被层层权限锁封闭的区域。","湛卢同步展开空间站结构图。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“先生，全站扫描完成。”","“下层区域存在大量生命信号。”","“其中包括低龄人类生命体。”","“同时检测到持续运行中的芯片植入设备、神经连接装置以及人体改造设施。”","陆必行脸上的轻松瞬间消失。","独眼鹰也收起了玩笑。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["林静恒看着那片黑暗区域。","声音很轻。","“他们把学生引进来的方向，和实验区重合了。”","“进去。”","空间站深处的通道比外层更加破旧。","金属墙壁上布满年代久远的锈迹。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["空气里混杂着消毒剂、营养液以及某种令人不舒服的血腥味。","越往里面走，机械运转声越清晰。","营养循环系统。","神经检测设备。","芯片植入仪器。","所有东西同时运行。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["像一台巨大而沉默的机器。","只是这台机器加工的，不是金属。","而是人。","通道尽头，一整排透明培养舱出现在众人面前。","陆必行停住了脚步。","他没有说话。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["甚至没有第一时间靠近。","因为眼前的一切，已经超过了语言能够描述的范围。","培养舱内，是一个个年幼的孩子。","他们被浸泡在营养液中。","年龄最大的不过四五岁。","有些孩子已经完成了芯片植入。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["胸口留下机械接口。","有些孩子还处于实验阶段。","连接线路从身体各处延伸出来。","冰冷的机器替代了本该属于生命成长的东西。","薄荷脸色一点点变白。","她来自孤儿院。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["她比很多人更清楚，被世界遗忘的孩子是什么样子。","怀特第一次没有说话。","那个平时最喜欢闯祸、最喜欢证明自己的人，此刻只是站在那里。","斗鸡甚至不敢继续看。","他本来就害怕精神网络。","现在看见这些孩子，他第一次意识到，有些东西比机甲失控更加可怕。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["黄静姝站在最后。","她的空脑症让她无法像普通人一样被某些精神影响完全遮蔽。","所以她听见了一些别人听不见的东西。","很轻。","很微弱。","培养舱里的孩子在哭。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["陆必行握紧了拳头。","他的第一反应是打开所有培养舱。","但手伸出去之前，又停住。","他很清楚。","这里不是普通实验室。","这些设备连接着大量数据。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["一旦强行破坏，所有证据都会消失。","那些孩子，也可能撑不过失控后的系统崩溃。","他闭了一下眼。","再睁开时，已经恢复冷静。","“湛卢。”","“扫描。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["湛卢走近培养舱。","机械探针展开。","“检测完成。”","“实验对象均为低龄人类幼儿。”","“芯片植入成功率不足百分之三十。”","“失败样本死亡率较高。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“造神计划目标：通过生物芯片强化人体机能，同时降低痛觉、恐惧等情绪反馈。”","“最终效果：制造失去自主意识的战斗单位。”","实验室陷入短暂沉默。","独眼鹰脸色铁青。","“他们把孩子当成什么？”","零件？材料？"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["林静恒没有回答。","他的目光停留在实验记录上。","大量编号。","大量失败。","大量死亡。","片刻后，他才开口："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“蜘蛛不是芯片的源头。”","“只是执行者。”","“真正需要这些实验数据的人，在这里。”","湛卢补充：","“先生。”","“检测到实验区域上方存在高级权限控制。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“有人正在接近。”","【零零一登场】","实验大厅上方。","脚步声缓缓响起。","零零一从阴影中走出。","他的身体经过大量机械改造。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["金属覆盖部分血肉。","机械与人体结合的位置留下明显痕迹。","但他的神情却异常平静。","甚至带着一种温和的笑意。","像一个正在向客人介绍自己作品的研究者。","而不是一个掌控人体实验基地的人。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“你们终于来了。”","零零一看着下方众人。","“其实我一直很好奇。”","“当你们亲眼看到未来的时候，会是什么表情。”","林静恒没有回应。","只是观察。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["他的目光扫过零零一身上的机械结构。","武器接口。","权限装置。","周围防御布局。","零零一抬手。","巨大的全息投影展开。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["改造人的实验影像出现在大厅中央。","那些经过芯片强化的人类，可以承受普通武器攻击。","但当能源耗尽。","强化效果消失。","身体也随之崩溃。","零零一看着画面。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["语气里带着近乎虔诚的狂热。","“联盟用了两百年告诉所有人。”","“人类应该接受自己的限制。”","“伊甸园告诉他们，秩序比自由重要。”","“但为什么？”","“为什么人类必须等待漫长进化？”"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“为什么不能主动改变自己？”","他看向培养舱里的孩子。","“他们不是牺牲品。”","“他们是未来的第一批新人类。”","陆必行终于开口。","“未来？”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["他的声音很轻。","“如果未来需要先毁掉一个人的选择权。”","“那它和灾难有什么区别？”","零零一看向他。","“你理解芯片。”","“你知道伊甸园。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“你知道技术可以改变生命。”","“但你却拒绝接受它。”","陆必行看着那些培养舱。","“我没有拒绝技术。”","“技术让人活得更好。”","“让人拥有更多选择。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“但如果技术最后只剩下一件事——替别人决定一个人应该成为什么。”","“那不是进步。”","“那只是另一种控制。”","零零一沉默片刻。","然后变本加厉地猖狂大笑。","“有趣。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“你和他们不一样。”","林静恒始终没有参与争论。","湛卢站在他身侧。","低声汇报：","“先生。”","“实验数据已全部备份。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“空间站通讯记录、芯片结构、实验参数均已保存。”","林静恒微微点头。","“继续。”","湛卢：","“先生认为，他们还有隐藏计划？”","林静恒看着零零一。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["“这些实验不是目的。”","“只是证明他们有能力做到。”","他的声音平静。","“真正的问题是。”","“他们准备拿这种能力做什么。”","【章节结尾】"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["零零一站在高台之上。","培养舱的冷光映在他半机械化的脸上。","而林静恒站在人群之中。","一个人在展示未来。","一个人在寻找未来背后的真相。","空间站的深处。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：毒巢鸿门宴","text":["还有更多未公开的秘密，正在等待揭开。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第五章：启明星的黎明与离别","text":["第五章：启明星的黎明与离别","章节开场","毒巢空间站的残骸漂浮在第八星系边缘深空，那些靠生物芯片操控孩童的人体实验卷宗，经由湛卢全部解密投影在银河城指挥大厅。","这场据点覆灭没有带来真正和平——造神芯片的复刻技术被多方势力截获，有人意图永久销毁，有人想改良牟利，还有人妄图复刻“完美人类”，借芯片奴役众生。","湛卢人形伫立，碧绿眼瞳铺满全域红色警报，语调平稳，不带半分情绪起伏：","“先生，全域溯源完成。造神芯片流通分三股势力：自由军团地下军火商、伊甸园管委会高层私库、林静姝专属加密通讯频道，匹配度99.7%，相关通讯记录已最高权限加密留存。”"],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第五章：启明星的黎明与离别","text":["林静恒指尖无意识摩挲吧台冷金属台面，眼底没有暴怒，只有一层沉郁疲惫。五年隐姓埋名蛰伏第八星系，本以为暂时隔绝沃托的权力泥潭，却不知祸根早已渗透身边。","“全部封存，禁止外流。”他声线压得很低，听不出波澜。","陆必行倚在操作台边，指尖无意识摩挲胸口——当年女娲计划刻在他骨血的烙印让他对这类控制类技术本能憎恶，温和笑意尽数褪去，只剩沉凝冷意。","一旁独眼鹰斜倚门框，鸳鸯眼沉沉扫过星图，陆信旧部的积怨翻涌眼底。他久居第八星系，极少接触沃托上层人物，只从零散情报里听过管委会那群掌权者的虚伪做派，分不清谁是格登，只知道沃托高层靠着伊甸网络玩弄权术，当年便是这群人联手构陷陆信。他看向林静恒，眼底混杂感激与隔阂：感激他守住八星系，又记恨联盟整体卸磨杀陆信，复杂矛盾一览无余。","独眼鹰闷声开口，语气裹着经年火气：“沃托那帮坐享其成的权贵，隔着几大星系都能把手伸过来折腾人命，当年陆将军就是栽在他们这套阴私算计里。”","【剧情推进】"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第五章：启明星的黎明与离别","text":["造神芯片的追查尚未落地，彩虹病毒骤然席卷七大星系。依托伊甸园精神网极速扩散，被联盟民众奉为救赎的精神网络瞬间沦为囚笼，无数人陷入幻觉、自残与集体暴乱，所有人第一次认清伊甸园暗藏的枷锁。","唯有从未完整接入伊甸园的第八星系守住秩序。这里世代被联盟抛弃，人人习惯失去，反而最懂如何互相托举。","独眼鹰掏空早年囤积的抗病毒原料，打通所有地下航道跨行星调配物资；林静恒不带白银武装，孤身穿行疫区搜集紧缺抑制剂；陆必行改造星海学院实验室，拆解简易检测仪器分发给各个聚居点，空脑症学生全员编入防疫小队——空脑症先天隔绝伊甸信号，是天然的防疫屏障。","漫长隔离期结束，启明星重建工程正式落地，荒芜戈壁上拔起银河城。星海学院新校区落成，空脑症收容中心、机甲工坊、信息研究院同步完工。陆必行亲自封存全部女娲人体改造资料，立下铁律：","“技术可以造器械、拓航道、医治病痛，但永远不能用来篡改人的意志，更不该定义谁是‘残次品’。”","入夜，整座银河城灯火顺着人工航道绵延至星海，曾经寸草不生的荒芜星球，第一次生出人间烟火。"],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第五章：启明星的黎明与离别","text":["陆必行凭栏吹风，晚风掀松他肩头外套，目光落向下方成片民居，语气轻得裹着陈年酸涩：","“从前北京β星的人，连做梦都不敢做得圆满，梦做多了，反倒要遭旁人取笑。久而久之，很多人干脆不再抱有期待，反正无论憧憬什么，最后都是一场空。”","林静恒站在他身侧，常年覆在周身的杀伐冷意淡去几分，灰色眼眸浸着整片城市灯火，沉默良久才开口，声音轻得会被晚风卷走：","“你建星海学院、重建这座城，只为争一口气？”","陆必行偏过头，眼底盛着细碎星光，惯有的玩笑腔调压下去，只剩坦荡坚定：","“不是争输赢。我只是想告诉那些空脑症、流离的孩子，他们生来不该被贴上残次品的标签，人生不必由别人提前写好结局。”"],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第五章：启明星的黎明与离别","text":["林静静静望着他，心底积压的负重悄悄松动。他半生扛着陆信遗恨、联盟背叛、与亲妹反目的三重枷锁，厮杀半生只懂以利刃止战；直到遇见陆必行才看清，原来守护也可以是温柔地为弱者撑起一片容身之地。","陆必行轻轻侧靠近半步，气息漫过晚风，带着一点试探的软意：","“等一切尘埃落定，你愿意留在启明星，不用再回那些刀光剑影的地方吗？”","林静恒喉间微紧，顿住许久没有作答。他心里藏着不敢宣的贪恋，却也清楚沃托、白银要塞的血海他终究避不开。","湛卢立于观景台暗处后台同步情绪分析，无外人听见的机械音单独录入存档：","【数据判定：先生心率小幅上浮，对陆必行信任度提升；陆必行情感倾向偏向长期共处羁绊，解锁前置线索「星海星火」】"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第五章：启明星的黎明与离别","text":["【互动选择一（前置路线倾向判定，影响双人羁绊解锁）】","选择一：【陪同陆必行去星海学院】","触发专属剧情：走访空脑症宿舍、机甲实训教室，旁听陆必行给孩子们讲课，完整窥见他“以文明容纳残缺”的核心理想，亲眼看见他将女娲计划的伤痛转化为庇护众生的温柔。","羁绊变化：陆必行信任度大幅提升，永久解锁双人温柔对话支线，解锁羁绊【星海星火】","选择二：【核查芯片与域外暗线】","触发专属剧情：跟随林遍历疫区据点、审问毒巢俘虏，见证他独自压下杀戮，尽力给普通人留生路的隐忍柔软，读懂他背负全联盟罪孽的将帅宿命。林静恒会顺带提起沃托管委会、林静姝布局的内情，提及沃托高层的一系列阴谋，仅说出“秘书长”头衔，不提及格登姓名。","羁绊变化：林静恒坦诚度提升，解锁隐藏心理描写支线，解锁羁绊【白银孤刃】","【剧情推进二｜黎明裂痕，战火将至】","启明星的安稳只是短暂幻象。林静姝暗中扶持自由军团批量改造芯片战士，伊甸园管委会借灾后管控强行植入民众精神调控模块，两方势力互相利用、蚕食星域权力，全面内战的警报拉响。","湛卢将全域战力推演投射在指挥大屏，冰冷数据刺破所有人的侥幸：","“综合军备、改造人储备、伊甸网络控制权测算，半年内八大星系全面内战爆发概率87.4%。”","陆必行指尖轻叩操作台，眼底笑意彻底敛去：","“永远有人自认手握最优解，总想着替全人类筛选‘完美人生’。”","林静恒侧眸看向他，眉峰微沉：","“你不认同这套逻辑？”","陆必行抬眼，语气温和却字字铿锵：","“绝不。人类的珍贵从来不是毫无瑕疵，恰恰在于我们会犯错、会煎熬，却依旧拥有自主选择人生的权利。技术是拐杖，不是锁住灵魂的牢笼。”","这是二人最深的共识，也是他们终将分赴两条道路的根源：一人愿以文明生根，一人必须执刃挡祸。","独眼鹰推门而入，手里攥着跨星域急报，只看懂“沃托高层内乱、白银要塞自爆”关键信息，不懂其中高层具体人名，语气沉重：","“沃托那边彻底乱了，当年陆将军拼下来的防线全塌了，那些躲在伊甸网络后面的权贵，终于闹到自相残杀。”","选择一：【扎根启明星】","核心立场：守住星海学院与八星系自治秩序，以教育与民生庇护所有被抛弃的人，拒绝以暴力循环对抗暴政。","解锁主线：《新星海时代》","角色倾向：温柔负重的文明守路人，解锁陆必行全部内心独白与温柔向单人剧情","选择二：【收拢白银十卫】","核心立场：唯有足够强悍的武装才能撕碎芯片奴役与伊甸管控，护住后方仅存的人间烟火。","解锁主线：《白银守护》","林静恒顺着陆必行的心意，默许他在机甲舱添置绿植加湿器，","时常让湛卢前往学院辅助授课，甚至暂时搁置筹谋多年的布局，","陪着他一点点完善学堂","在外人人都畏惧杀伐果决的黑洞四哥，","面对陆必行会卸下一身尖刺，","实打实的付出默默托举对方旁人眼里荒唐的理想","后来，","战火尚且蛰伏在遥远星海，","彩虹病毒、域外海盗、联盟阴霾层层笼罩第八星系，","淤泥遍地的荒芜星域里，","怀揣理想的少年与满身旧伤的上将彼此牵绊，","未曾宣之于口的缱绻情愫，","藏在实验试剂、废弃机甲与漫天星河之间，","安静等候那场遥遥无期的长久别离。","仿佛理想主义化身的少年用纯粹与特别，","在岁月里雕刻着腥风血雨里脱身的将军","“我不用你承诺什么，但无论多远，记得回来。”","【剧情推进】","沃托动乱、白银要塞化为焦土的跨星域消息传来，沉寂五年的白银十卫加密通讯频道全线重启，散落各地旧部等候统帅归位。","湛卢投影联盟上将全套权限档案，冷白肩章虚影悬在二人之间：","“先生，联盟军委遗留指令全部解锁，您的上将身份正式恢复，全域刺杀目标置顶。陆校长无随军作战规划，将长期留守启明星。”","林静恒指尖虚碰虚拟肩章，动作滞涩一瞬，五年四哥的闲散伪装彻底剥落，肩上重新扛起整片星海的生死重担。","“我知道。”他低声回应，语气里听不出波澜，只有湛卢能捕捉他转瞬低落的情绪。","湛卢如实上报数据分析：“后台情绪监测显示，您潜意识极度希望带陆校长同行，但理智判定启明星无人镇守，不能托付。”","林静恒没有否认，只抬眼望向窗外银河城灯火，轻声自语，只有自己能听见：","“我不想让他沾半点硝烟。”","一旁独眼鹰靠墙壁静静听完全部对话，鸳鸯眼沉沉打量林。他不懂沃托高层的派系厮杀细节，只清楚眼下席卷八大星系的动荡需要有人挡在前面，终究只是闷哼一声，不再出言阻拦。","【剧情推进】","启明星主星港，白银巨型舰队整齐列阵，跃迁引擎预热，冷金属光铺满整片停机坪，凌晨黎明薄雾裹着刺骨深空寒气。","陆必行独自赶来送行——他太懂林肩上背负的责任，所以不想用私情困住对方。","二人隔着数步距离，身后是万家灯火，前方是无边战乱星海。","陆必行先开口，照旧用轻松调侃藏起心底酸涩：","“别人出征好歹有个准信，到你这里，从来说不清什么时候回。”"],"choices":[{"title":"陪同陆必行去星海学院","key":"route_142_0"},{"title":"核查芯片与域外暗线","key":"route_142_1"},{"title":"扎根启明星","key":"route_142_2"},{"title":"收拢白银十卫","key":"route_142_3"}],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第五章：启明星的黎明与离别","text":["林静恒望向他，常年覆在眉眼的寒霜软下一层，声音很低，只有两人能听清：","“我给不出确切归期，乱世没有人能打包票。”","陆必行收敛玩笑，往前半步，距离分寸刚好不逾矩，目光牢牢锁在林脸上，轻声唤那个只属于他的称呼：","“林。”","林静恒应声抬眼。","陆必行字字清晰，没有哭闹纠缠，一句托付即是全部心意，复刻原文内核："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第五章：启明星的黎明与离别","text":["“不用硬撑着所有人的安危不顾自己。启明星我守着，我等你回来。”","林静恒喉间微涩，征战半生，千万将士、整片联盟他都扛过，唯独眼前这个人，是他唯一不敢赌的软肋。他没有多余抒情，只道一句托付，拆分两层重量：","“启明星交给你。”","陆必行挑眉，带一点浅淡笑意，冲淡离别压抑：","“联盟上将的军令？”","林静恒深深凝住他，灰色眼底翻涌从未外露的信赖与藏了五年牵挂，一字一顿："],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第五章：启明星的黎明与离别","text":["“是命令。”","星港引擎低鸣盖住细碎风声，后半句轻得像心底私语，他唯一一次卸下铠甲的真心话：","“也是我的托付。”","他征战半生，守护过沃托、守护过万千星域众生，却从没有一处人间、一个人值得他交付全部退路。唯有启明星，唯有陆必行，是他跨越星海也要奔赴的归途。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第五章：启明星的黎明与离别","text":["【隐藏小剧场已解锁】","点击下方按钮，阅读《十六年》。"],"choices":[],"plugin":{"title":"十六年","label":"隐藏小剧场","content":["他在第七星系的战火中失了踪影。林静恒最后的消息，是图兰报告里一串冰冷的坐标——跃迁点爆炸，指挥舰解体，白银十卫几乎尽数折损其中。陆必行盯着通讯屏幕上那条终于归于静默的信号线，觉得自己也随那场爆炸碎在了星海尽头。","此后十六年，第八星系成了一个孤岛。","陆必行把破碎的自己一片一片捡回来，拼成一个还能站立的人。他在凌晨四点看军工厂的报表，在午夜的办公室里批阅重建规划，在所有能挤出的时间里，修复那个再也等不到主人的人工智能。湛卢的机械手在实验室里一次次亮起又熄灭，像一只固执的萤火，照着一个人不肯熄灭的念想。","他偶尔会在某个极其疲惫的深夜，恍惚间听见走廊尽头有熟悉的脚步声，回头时只有自己拉长的影子。","而那个人其实还活着。","林静恒被林静姝困在一个与世隔绝的小行星上，在生态舱里昏睡了整整两年。他的意识像一缕将断未断的丝线，悬在生与死的罅隙里，每一次试图挣脱都撞上冰冷的屏障。他尝试了两千余次的越狱，犹如冷静而固执的困兽。","他不说话，不挣扎，不向任何人示弱，只用自己的眼睛一点一点地丈量这方牢笼的每一道裂缝。又在某个恒星风暴过境的深夜，借着那片短暂紊乱的能量场，生生从那副生不如死的躯体里撕出一条生路。","他花了十六年，从灰烬里爬回人间。","而陆必行，用了同样的十六年，让自己长成能接住这个人的模样。","当虫洞再次撕裂时空，当那架破旧的小机甲终于穿过玫瑰之心的乱流出现在启明星的天际线上时，陆必行没有哭。他只是站在机甲站的监控镜头前，看着那个瘦得几乎脱了形的人，一步一步走下舷梯。","像等了一辈子的月亮终于回到海上，他不敢大声呼吸，怕惊散了这漫长的长夜。","陆必行走进指挥中心时，那针舒缓剂六号的血药浓度刚好攀上峰值。他的步伐平稳，脊背笔直，同每一个向他汇报的卫兵点头致意，声音里听不出半分波澜。只有林静恒第一眼就看见了他微微发红的眼白——那是药物强行压下某种激烈情绪留下的痕迹。","两人之间隔着半个指挥大厅。","满室的人来人往忽然褪了色。陆必行把目光钉在全息星图上，手指落在某一处坐标上停了半秒，又若无其事地移到下一处。他没有回头，没有失态，甚至没有让呼吸乱上一拍。","林静恒靠在门框边，瘦得肩骨支棱着衬衣，脸上还带着久不见光的苍白。他也没有动。他隔着半个大厅看那个人的背影，看到陆必行的站姿变了——以前那个人站着总要歪一点，肩是松的，像随时准备转身跟人说笑；现在他站得笔直，每一块骨头都卡在应该在的位置上。","这十六年，陆必行学会了把自己装进一副严丝合缝的壳里。","然后陆必行转过身来，隔着半个大厅对他笑了一下。那个笑容浅得几乎称不上笑，只是唇角松了松，眼里却一点波纹也没有，像一面快裂了却还在勉力撑着的冰。","林静恒忽然觉得胸口那根肋骨疼得有点过分——也许是当年在太空监狱里断过的那一根。他从不习惯在人前示弱，于是他挑了挑眉，用那种漫不经心的、欠揍的腔调开了口：","“演得挺像。”他说，“跟谁学的？”","陆必行的嘴角又往上提了一点点，幅度小得几乎让人疑心是错觉，像是他整个人已经被那针舒缓剂六号冻住了，只剩这一丝薄薄的弧度还在勉强替他活着。他没有回答这句话，只是用一种极轻极静的语气说：“统帅，欢迎回来。”声音平得像在念一份军需报表，十六年的等待压进去，竟连一个颤音也没剩。","林静恒垂下眼。他想：原来被人用自己惯用的方式对待，是这种滋味。他花了半辈子用这套把戏把所有人推远，现在终于有人学会了，连本带利地还回来。而他无话可说，因为是他教的。","跃迁点的感觉还在身上，十六年的爱人生离死别后的重逢。","至此","黯淡了十六年的星星","于淤泥中间熠熠发光"]},"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第六章：玫瑰之心","text":["第六章：玫瑰之心"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第一幕","text":["第一幕","【白银旗舰「湛卢号」指挥大厅】","整片星域星图铺满灰红交错的警报色块，林静姝改造人军团像蜂群填满跃迁航道。鸦片芯片植入颅腔，抹除恐惧、痛感、自我意识，敌军机甲驾驶员只剩单一杀戮指令，常规编队接触片刻便全线溃散，残骸漂浮在无光深空，像一滩滩失去魂魄的躯壳。","湛卢人形立在指挥台侧，碧绿光屏滚动冰冷演算数据，语调平直，不带半分人为情绪，只有数据陈述：","“先生，全域战损实时更新。改造单位无上限持续增援，常规正面围剿战术综合胜率27.3%。鸦片芯片可强行改写人类精神阈值，普通驾驶员接入战场三小时，自我认知会彻底消融。”","指挥厅内一片死寂。图兰指尖死死扣住操作台边缘，眼底压着一层不忍，望着星图上密密麻麻的红标，低声开口："],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第一幕","text":["“我们要打的从来不是敌军，是一群活生生被人剥走‘自己’的普通人。”","林静恒垂眼落在星图上，指尖无意识摩挲肩章磨旧的纹路。十六年隐姓埋名躲在第八星系，以为能暂时躲开联盟积压的所有祸根，到头来陆信的旧仇、林家兄妹的隔阂、全星系人的苦难，尽数堆在他面前。他说话声音很轻，没有激昂控诉，只一句冷透的断论：","“她造的从不是兵器，是一群失去选择权的人。”"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第一幕","text":["【玩家前置双线互动选择（绑定羁绊、专属战场剧情解锁，游戏机制完整保留）】","选择一：【白银锋刃·全域分割围剿】","路线归属：白银守护主线","羁绊变化：\n林静恒信任度大幅上涨，白银十卫全员好感解锁，解锁人物隐藏过往回忆","专属触发剧情：","跟随林静恒制定跃迁点封锁战术。战前他会先划出大片平民与俘虏撤离空域，优先规划保全普通人退路，再谈清缴敌军。能窥见他骨子里厌弃杀戮，却不得不扛起屠刀的挣扎。","专属解锁线索：","白银要塞遗留重型屏蔽武器档案、改造芯片物理爆破参数。","选择二：【溯源拆解·寻觅芯片先天死穴】","路线归属：文明破解主线","羁绊变化：\n陆必行双向信任同步提升，湛卢解锁哈登博士加密底层实验卷宗","专属触发剧情：","湛卢搭建加密跨星通讯，实时同步银河城实验室数据。远程旁观陆必行带领空脑学生推演芯片缺陷，知晓空脑症先天隔绝鸦片精神干扰这一破局关键。","专属解锁线索：","女娲计划原始人体实验记录、空脑精神屏障完整理论。"],"choices":[{"title":"白银锋刃·全域分割围剿","key":"route_150_0"},{"title":"溯源拆解·寻觅芯片先天死穴","key":"route_150_1"}],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第二幕","text":["第二幕","【星海学院地下档案室，遮光光屏映满冷白字迹】","陆必行调取哈登遗留最高权限封存档案，层层拨开林静姝从乌兰天才滑向深渊的整条轨迹。少时与兄长被迫拆分，常年困在伊甸园情绪管控下，自幼认定痛苦、软弱、残缺都是文明累赘，最终借鸦片芯片妄图一刀切，抹掉所有人性里的“瑕疵”。","独眼鹰守在密室门外，鸳鸯眼沉得像积了百年乌云。作为陆信旧人，他比谁都清楚联盟上层如何磋磨林家姐弟，一声闷叹压在喉间，没进来打扰室内人。","光屏上少年时期的林静姝眉眼尚干净，陆必行长久静立，半晌才低声开口，语气里没有纯粹憎恶，只剩一层绵长惋惜：","“她分得清芯片会伤人，只是笃定只要目标足够宏大，所有个体的悲欢、苦难，都可以被牺牲。”"],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第二幕","text":["湛卢同步调取跨星域情报比对，光屏跳出双方通讯溯源记录：","“数据匹配完成，林静姝所有武装布局依托鸦片芯片扩张，但核心诉求并非占领星系，而是彻底剔除人类与生俱来的不完美。”","陆必行垂眸，脑海里浮现星港别离那日林静恒沉默的侧脸。他终于懂了对方长久回避这个名字的缘由——那不是无关仇敌，是血脉至亲一步步走到对立面，是跨越十六年解不开的遗憾与两难。","晚风从通风口溜进档案室，掀动一页泛黄的实验纸，纸上写着哈登那句批注：人之所以为人，在于敢接纳自己的裂痕。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["第三幕","【玫瑰之心外围中央军主舰指挥舱】","伊甸园管委会借精神网络钳制全民情绪，林静姝在外以芯片军团蚕食星域，战火撕裂八大星系。伍尔夫手握联盟仅存完整中央机甲军团，站在两条歧路中间，抛出一套折中制衡方案。","老元帅一身落满硝烟的旧军装，眼底藏着半生疲惫，语气沉缓，无半分空想的狂热：","“人类所有战乱，根源都出自欲望、恐惧、爱恨这类非理性情绪。以军政体系约束伊甸权限、限制芯片流通，人为抹平极端矛盾，便能换来长久无硝烟的平稳。”","光屏铺开全域模拟推演，画面里众生无悲无怒，没有冲突，也没有心动与遗憾，是一座规整却死寂的人造乌托邦。"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第三幕","text":["陆必行远程接入跨星通讯，没有立刻反驳，安静听完整套推演，停顿片刻才缓缓开口，语调温和却立场坚硬，字字扣着“残次品”的底色：","“倘若世界再也容不下犯错、煎熬、心动这些不完美，那活在里面的，还能叫做人吗。”","伍尔夫眉头微蹙，语气带着历经战乱的固执：","“稳定是文明存续第一要务。”","“稳定不该以剥夺选择为代价。”","陆必行抬眼，脑海里掠过星海学院一屋子空脑孩童："],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第三幕","text":["“文明存续的根基从不是标准化的平静，是人有权利走一条属于自己的路，哪怕这条路布满差错。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"关键主线锁定抉择（永久划分结局解锁门槛）","text":["【关键主线锁定抉择（永久划分结局解锁门槛）】","选择A：【接纳均衡管控秩序】","解锁主线：机械均衡线","路线后果：","第八星系纳入联盟统一管控，星海自由教学权受限，空脑、残次品依旧会被系统标记为不稳定隐患；解锁伍尔夫晚年自我怀疑私密手记。","选择B：【死守人类自主选择权】","解锁主线：星火传承线","路线后果：","联合空脑军团与白银援军缔结跨星系同盟，完整解锁哈登全套制衡理论；为隐藏结局必备前置条件。"],"choices":[{"title":"接纳均衡管控秩序","key":"route_156_0"},{"title":"死守人类自主选择权","key":"route_156_1"}],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第四幕","text":["第四幕","【十六年牵挂】","玫瑰之心虫洞引力持续干扰信号，两道跨星域通讯窗口艰难同步亮起。","一侧是白银旗舰满是炮火划痕的指挥台，林静恒一身征尘，眼底藏着十六年遥遥相隔的忐忑；一侧是银河城观景台，陆必行身后绵延整片城市灯火。相隔亿万光年，理念相悖之下，藏着没说出口的惦念，对话无直白告白，所有情绪压在停顿与眼底。","陆必行先开口，惯有的松弛调侃压下心底沉甸甸的忧虑，轻得像一阵晚风：","“你计划摧毁全部鸦片芯片生产基地，连那些本可用来修复神经损伤的改良样本，也一并销毁？”"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第四幕","text":["林静恒指尖无意识擦过光屏上陆必行模糊轮廓，沉默许久，声线裹着十六年积压的亏欠，低沉沙哑：","“只要技术的前提是夺走人的自我，便没有留存的资格。”","陆必行低头浅浅笑了一下，笑意浮不到眼底，藏着多年了然：","“从前我总觉得，你太过信奉兵刃能了结一切纷乱。”","林静恒抬眼，穿过漫天星尘望向屏幕里的人：","“如今怎么看？”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四幕","text":["“如今懂了。”","陆必行声音放轻，隔着星尘传递：","“你从不是嗜杀，只是比任何人都恐惧，有人擅自替旁人敲定一生的路。”","林静恒没有否认，长久静默。十六年前被迫凭空消失，十六年后战火再一次把二人拆分，他心里藏着一句不敢出口的怕——怕此战过后，又是十数年遥遥相隔。","湛卢后台同步情绪记录，光屏小字无声滚动：","双向羁绊数值大幅上涨，解锁隐藏结局前置判定项。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第五幕","text":["第五幕","【玫瑰之心虫洞】","玫瑰之心天然巨型虫洞横亘在八大星系航道中央。","这里曾是连接无数星域的交通枢纽，如今却成为战争最残酷的绞杀场。","折断的机甲残骸漂浮在虫洞边缘，废弃芯片碎片随着引力乱流缓慢旋转，失去控制的能源光束不断撕裂黑暗深空。","三方势力在此汇聚。"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第五幕","text":["一方，是以林静姝为核心的改造人军团。","一方，是以林静恒率领的白银十卫。","另一方，是仍在观望中的中央军。","【林静姝星舰】","主舰静静悬浮在虫洞最深处。","指挥舱内没有战前紧张的喧嚣，反而安静得近乎诡异。"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第五幕","text":["林静姝坐在主控台前，手边放着一束蔚蓝之海。","那是她记忆里曾经属于旧日故乡的花。","花瓣脆弱，颜色浅淡，仿佛随时会在宇宙风暴中凋零。","她低头修剪枝叶，外界震耳欲聋的炮火声仿佛与她无关。","通讯频道里不断传来战报。","“第七舰队防线突破。”"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第五幕","text":["“改造军团已进入第二跃迁节点。”","“芯片同步率保持百分之九十八以上。”","林静姝只是轻轻应了一声。","“继续。”","她看着手中的花，声音很轻。","“如果人类永远无法摆脱痛苦，那就替他们拿走痛苦。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第五幕","text":["“这有什么错。”","【白银军舰】","另一端。","白银十卫舰队排列成锋利阵型，像一把刺入黑暗的银色长刃。","泊松杨、图兰、金等白银十卫成员分别镇守各处跃迁节点。","湛卢人形站在指挥台旁，碧绿色光学眼不断刷新战场数据。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第五幕","text":["“先生，敌方改造单位数量持续增加。”","“当前战场环境下，普通精神防御系统无法抵御芯片干扰。”","“建议优先破坏中央控制节点。”","林静恒站在主控台前。","他没有看那些不断跳动的伤亡数字，而是盯着敌方舰队后方那些被芯片控制的驾驶员编号。","那些编号后面，曾经都是活生生的人。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第五幕","text":["普通士兵。","年轻驾驶员。","甚至还有被强行改造的平民。","湛卢停顿片刻。","“先生。”","“根据历史数据分析，您当前决策压力指数超过正常范围。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第五幕","text":["林静恒淡淡道：","“湛卢。”","“重新调整攻击策略。”","“优先解除芯片控制，降低人员伤亡。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第五幕","text":["【玩家战场选择】","选择一：【白银突破核心舰队】","路线归属：白银守护线","触发剧情：","玩家跟随林静恒进入主战区域。","林静恒亲自制定跃迁封锁方案。","他没有第一时间下达歼灭命令，而是在星图上划出数条撤离路线。","湛卢询问：","“先生，按照传统军事方案，优先摧毁敌方主力舰队，可提高胜率。”","林静恒看着那些撤离航线。","“战争不是为了证明谁更擅长毁灭。”","“先救人。”","“再结束战争。”","获得线索：","白银要塞遗留屏蔽武器档案","改造芯片物理破解方案","林静恒隐藏军事档案","羁绊变化：","林静恒信任度提升。","白银十卫认可度提升。","解锁：","【白银孤刃】","选择二：【寻找芯片破解方法】","路线归属：星海火种线","触发剧情：","玩家跟随陆必行远程技术线。","银河城实验室内。","陆必行带领空脑症学生破解芯片底层代码。","空脑症天然隔绝伊甸园精神信号，成为整个战争中唯一不受芯片影响的人群。","实验室里，少年们第一次成为拯救星系的关键力量。","陆必行看着满屏数据，轻声说道：","“他们一直认为我们是不完整的人。”","“可偏偏是这些所谓的不完整，救了所有人。”","湛卢同步传输数据。","“检测完成。”","“空脑精神屏障可有效隔离芯片控制信号。”","“建议建立全域保护网络。”","获得线索：","女娲计划原始档案","空脑精神屏障理论","芯片核心漏洞","羁绊变化：","陆必行信任度提升。","解锁：","【星海星火】"],"choices":[{"title":"白银突破核心舰队","key":"route_168_0"},{"title":"寻找芯片破解方法","key":"route_168_1"}],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第六幕","text":["第六幕","【林静姝通讯接入】","战场中央。","林静姝突然接入全域通讯。","她的声音没有愤怒，也没有胜利后的狂热。","只是平静。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第六幕","text":["像是在陈述一个早已确定的答案。","“哥哥。”","“你真的认为，人类可以靠自己走下去吗？”","林静恒没有回答。","林静姝继续说道：","“他们会恐惧，会贪婪，会战争，会互相伤害。”"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第六幕","text":["“他们需要一个更高层次的管理者。”","“需要有人替他们选择。”","巨大的虫洞光芒映照在林静恒眼中。","他终于开口：","“所以你认为。”","“夺走选择权，是保护。”"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第六幕","text":["林静姝轻声道：","“至少比让他们继续痛苦好。”","林静恒沉默片刻。","“你错了。”","“人活着，不是为了避免所有痛苦。”","“而是有资格决定自己承受什么。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第六幕","text":["【关键主线选择】","选择A：【接受均衡秩序】","路线解锁：机械均衡线","玩家认可伍尔夫方案。","以最高效率结束战争。","代价：","人类获得稳定，却逐渐失去自主。","星海学院受到联盟统一管理。","空脑症仍被视为特殊风险群体。","选择B：【守护自主选择】","路线解锁：星火传承线","玩家拒绝所有强制控制方案。","联合白银十卫、空脑军团以及第八星系力量。","目标：","不是创造完美世界。","而是守住每个人选择人生的权利。"],"choices":[{"title":"接受均衡秩序","key":"route_173_0"},{"title":"守护自主选择","key":"route_173_1"}],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第七幕","text":["第七幕","【玫瑰之心虫洞核心区域】","战争持续了整整三十七小时。","虫洞外围漂浮着无数舰船残骸，能源光束逐渐熄灭，只剩下破碎的警报声在深空中回荡。","曾经象征星际交通与文明连接的玫瑰之心，此刻成为决定八大星系未来方向的战场。","三条道路，在这一刻交汇。"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第七幕","text":["【路线一：白银守护】","解锁条件：","全程选择【白银锋刃】路线；","未完成双线羁绊；","未收集完整芯片破解资料。","【白银军舰】"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第七幕","text":["林静恒站在指挥台前。","星图上，林静姝主舰的位置不断闪烁。","湛卢低声汇报：","“先生，敌方核心能源节点已暴露。”","“当前攻击成功率：86.9%。”","“预计造成不可逆损毁。”"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第七幕","text":["林静恒沉默片刻。","他知道。","这一击之后，造神芯片体系会彻底崩塌。","也意味着无数被卷入战争的人，将无法再回头。","湛卢看向他。","“先生。”"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第七幕","text":["“是否执行最终攻击？”","林静恒望着那些红色标记。","许久。","他说：","“执行。”","白银十卫突破最后防线。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第七幕","text":["湛卢机甲化作一道银色流光，穿过虫洞乱流。","通讯里，","兄妹二人再次相见。","一个站在人类未来的另一端。","一个站在守护过去的废墟里。","林静姝看着他，轻声说："],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第七幕","text":["“静恒，”","“你还是选择他们。”","林静恒没有回答。","只是看着她。","那个曾经跟在自己身后的妹妹。","战争结束。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第七幕","text":["造神芯片生产链被摧毁。","结局评价：","【白银守护】","你选择成为一把刀。","不是因为喜欢杀戮。","而是因为总要有人握住刀柄，替后来的人挡住黑暗。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第七幕","text":["核心关键词：","孤刃、责任、牺牲、遥遥守望。","【路线二：新星海时代】","解锁条件：","全程选择【溯源芯片】路线；","未完成白银战场全部线索；"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第七幕","text":["未触发隐藏双线结局。","【银河城·星海学院】","战争最后阶段。","陆必行没有选择摧毁所有芯片。","而是选择破解。","他知道。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第七幕","text":["技术本身没有善恶。","真正危险的是那些试图利用技术替所有人决定未来的人。","实验室里。","无数空脑学生围绕主控屏幕。","年轻的学生紧张地看着数据。","“校长，如果失败……”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第七幕","text":["陆必行笑了一下。","还是那个熟悉的、总喜欢给别人希望的人。","“失败也没关系。”","“人类又不是第一次失败。”","“重要的是，我们失败之后，还有重新选择的机会。”","芯片控制网络逐渐瓦解。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第七幕","text":["伊甸园精神干预系统被重新限制。","八大星系重新建立自治协议。","星海学院成为新的文明核心。","这里不再区分：","正常人。","空脑症。"],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第七幕","text":["所有孩子都可以拥有属于自己的未来。","结局评价：","【新星海时代】","你没有选择成为最锋利的武器。","你选择守住一颗星球，一群孩子，以及人类仍然可以犯错的未来。","核心关键词："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第七幕","text":["文明、包容、教育、星火传承。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"隐藏终极结局","text":["【隐藏终极结局】","玫瑰之心共生","解锁条件：","必须同时满足：","◆ 第五章解锁：","【十六年星火】"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"隐藏终极结局","text":["【十六年孤刃】","双羁绊。","◆ 第六章完成：","【白银锋刃】","与","【溯源芯片】"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"隐藏终极结局","text":["双路线。","◆ 主线选择：","【死守人类自主选择权】","◆ 收集：","林静姝完整档案；","伍尔夫元帅理念档案；"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"隐藏终极结局","text":["哈登博士实验记录。","也许某一个清晨，","林将军和工程师001家里的阳台上，","林静恒站在那里。","陆必行站在他身旁。","两个人都没有说话。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"隐藏终极结局","text":["战乱时生出的牵挂，","相思相守的情愫，","无数次错过。","无数次擦肩。","最终都停在了这里。","“我到淤泥深处”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"隐藏终极结局","text":["“捡到了一颗星星”","湛卢悬浮在两人之间。","光屏亮起。","“八星系新一任政府接触结构构建完成。”","“工程部报告星海学院建设完成。”","这种一派向好的局面，"],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"隐藏终极结局","text":["事儿精的湛卢也许会检测状态数据，","“适时”感慨上一句吗，","“人类文明不存在唯一正确答案。”","“拥有选择本身，即为答案。”","湛卢记录。","【检测结果：】"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"隐藏终极结局","text":["【统帅情绪稳定。】","【长期压力指数下降。】","【愉悦类激素水平提升。】"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"建议保存该历史节点。","text":["【建议保存该历史节点。】","两个人并肩站在银河城最高处。","看着这片曾经被称作荒漠的土地。","一点一点。","长出文明。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第六章终章","text":["第六章终章","玫瑰之心的硝烟终会散去。","战争留下的伤痕不会立即消失。","但废墟之上，总会有人重新种下种子。","有人选择成为利刃。","替众生挡住黑暗。"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第六章终章","text":["有人选择成为灯火。","替后来者守住方向。","人类从来不会因为完美而伟大。","真正珍贵的，是明知自己会犯错。","依旧愿意选择。","愿意爱。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第六章终章","text":["愿意承担。","愿意在漫长宇宙中，寻找属于自己的道路。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"主线通关","text":["【主线通关】","获得永久称号：","「星海守望者」","官方评价：","你没有创造一个没有痛苦的世界。","你守住的是——"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"主线通关","text":["即使身处黑暗，人类依然拥有选择未来的权利。","《第八星系风云》","林静恒主线剧情·完"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"}]},{"id":"陆必行","name":"陆必行","source":"陆必行主线(5).docx","portrait":"人物图片/陆必行.jpg","subtitle":"星海星火","accent":"#d6ad62","scenes":[{"chapter":"序章","text":["《第八星系风云》","陆必行主线·星海拾光"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一章","text":["第一章","《荒漠遗孤》","【章节时间】","新星历250年前后","【章节地点】","第八星系·凯莱星"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第一章","text":["【章节主题】","女娲宿命烙印、先天残缺的困顿、无根无籍的幼年困境。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["第一幕","【第八星系·凯莱星】","第八星系。","联盟疆域最偏远的角落。","这里没有核心星系的繁华。","没有伊甸园体系下完整稳定的秩序。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第一幕","text":["这里只有荒芜星球、废弃航道，以及被文明遗忘的人群。","而陆必行。","从出生之前，就已经背负了一份来自旧时代的烙印。","陆信蒙冤。","母亲死难。","尚在母体中的陆必行，又遭遇了致命宇宙辐射。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第一幕","text":["按照正常情况。","这个孩子本该无法出生。","他的生命，本该停留在那个冰冷的实验数据里。","然而。","独眼鹰救下了濒死的胚胎。","依靠残留的女娲计划技术。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["借助彩虹病毒相关改造手段。","他将这个几乎无法存活的生命，从死亡边缘硬生生拉了回来。","因此。","陆必行从出生开始，就并非一个完整意义上的自然人。","他是女娲计划遗留下来的半成实验载体。","【凯莱星·幼年时期】"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第一幕","text":["幼年的陆必行身体状况极差。","先天基因残缺。","精神网天然断裂。","他无法像其他孩子一样，顺利接入伊甸园公共精神系统。","别的孩子可以轻易连接公共网络。","接受信息。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["维持稳定精神链接。","而他却经常陷入短暂的失神。","意识像被隔在某个遥远的地方。","无法完全回应外界。","他的身体同样脆弱。","幼年时期。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["莫名的心悸。","感官错位。","精神疲惫。","这些伴随着他的成长。","他的身体，比普通孩子更加容易受到伤害。","他没有合法户籍。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["没有完整基因档案。","在联盟文明体系里。","他只是一个没有来源记录的人。","一个默认被遗弃的“残次品”。","年幼的陆必行并不知道：","什么是人体实验。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第一幕","text":["什么是女娲计划。","什么是宿命。","可是他本能地感受到了一件事。","自己。","和别人不一样。","旁人的人生似乎理所当然。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["出生。","成长。","连接伊甸园。","拥有身份。","一切顺理成章。","可是到了自己这里。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["却总带着一些无法解释的异常。","周围人的疏离。","隐晦的观察。","偶尔落在身上的戒备目光。","成为了他童年最熟悉的东西。","“为什么别人可以这么自然地存在？”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["“为什么只有我，需要证明自己为什么存在？”","他从未犯错。","却从出生开始。","就像背负了一份无法解释的罪。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["第二幕","【凯莱星·旧档案库】","很多年里。","所有关于陆必行身世的信息，都被独眼鹰牢牢封存。","他不希望这个孩子过早知道自己的过去。","可是。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第二幕","text":["隐藏的真相，终究会有被发现的一天。","年幼的陆必行偶然接触到了一份残缺实验档案。","冰冷的数据缓缓展开。","实验记录。","修复数据。","残损样本标注。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["那些陌生又冰冷的文字，一点点拼出了一个他从未想过的答案。","他的降生。","不是普通意义上的出生。","而是旧时代实验留下的一次意外存续。","那一刻。","长久以来隐藏在心底的不安。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["第一次拥有了名字。","如果自己的身体。","来自人为修复。","如果自己的存在。","只是某个旧时代计划留下的结果。","那么。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["现在的自己。","究竟算不算真正的自己？","“如果我的身体不是自然形成的……”","“如果我的存在，从一开始就被别人决定……”","“那么我现在拥有的一切，到底属于谁？”","幼年的困惑。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["身体的异常。","无法融入世界的孤独。","在这一刻全部交织在一起。","他仍然无法回答。","也没有人能够替他回答。","只是从这一刻开始。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["那个关于“我是谁”的问题。","深深埋进了少年陆必行心里。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["【玩家选择】","选择一：","【隐藏异常】","剧情：","陆必行选择隐藏自己的异状。","他本能地收敛所有特殊表现。","在人群中降低存在感。","习惯观察。","习惯隐藏。","习惯保护自己。","获得：","【隐忍值】","解锁：","察言观色、隐藏自身的洞察能力。","选择二：","【研究自身】","剧情：","面对身体上的异常与身世谜团。","陆必行开始主动观察自己的精神状态与身体变化。","试图从最初的源头，寻找自己与常人的不同。","获得：","【科研值】","解锁：","女娲计划、精神网络初步探索支线。","选择三：","【帮助同类】","剧情：","因为自己曾经历过“不被接纳”的困顿。","陆必行开始本能关注那些同样被世界遗忘的孩子。","那些没有身份。","没有归属。","被文明排斥的人。","获得：","【文明值】","解锁：","众生平等的初心内核。"],"choices":[{"title":"隐藏异常","key":"route_22_0"},{"title":"研究自身","key":"route_22_1"},{"title":"帮助同类","key":"route_22_2"}],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一章结尾","text":["第一章结尾","【凯莱星·夜晚】","荒凉星球的风吹过废弃街道。","幼年的陆必行仍然无法摆脱身体上的缺陷。","也无法真正理解自己的过去。","他还没有力量改变什么。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第一章结尾","text":["也没有能力挣脱命运留下的枷锁。","但是。","在漫长的迷茫与困顿里。","他第一次记住了一件事。","自己与别人不同。","但不同。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一章结尾","text":["并不代表错误。","那个尚且年幼的孩子。","在荒芜星海的角落里。","沉默承载着旧时代实验落在自己身上的枷锁。","等待未来某一天。","亲自回答："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一章结尾","text":["“我究竟是谁。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二章：凯莱旧梦","text":["第二章：凯莱旧梦","【章节加载】","时间：\n新星历250年前后—少年时期","地点：\n第八星系·凯莱星","章节主题：\n粗粝乱世里的双向羁绊、笨拙纵容的父爱、荒星唯一的归处、残缺少年的安稳一隅"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第一幕","text":["第一幕","【第八星系·凯莱星】","荒芜星海缓缓掠过。","破败星球悬浮在深空之中，残旧的空间站、废弃航道、失修的军用设施遍布星球表面。","这里没有核心星域的繁华，也没有联盟文明宣扬的秩序。","只有废墟、流民、黑市与漫长的生存挣扎。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第一幕","text":["第八星系，是联盟文明刻意划开的死角。","这里没有伊甸园精准规整的精神滋养，没有核心星域的秩序与礼法，更没有人人平等的生存权利。","整片星海荒芜暴戾，星盗横行、黑市猖獗、法则失效，普通人活着的唯一目的，只是撑过当下、苟活朝夕。","【凯莱星·城市外围】","破旧街道上，废弃机甲残骸堆积成山。","老旧工坊冒出机械蒸汽，黑市交易者穿梭其中。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第一幕","text":["孩子们在残破街巷里奔跑，却没有多少笑声。","生于这片废土的人，大多麻木、狡黠、不信善意、不信未来。","凯莱星盘踞在荒芜星海深处，遍地废弃军工残骸、陈旧空港与阴暗街巷，是乱世之中藏污纳垢的夹缝之地。","就是这样一座人人自危的荒星，却为陆必行留存了一方截然相反的净土。","庇护他的人，是他父亲独眼鹰。","【凯莱星·独眼鹰机甲维修工坊】"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第一幕","text":["昏暗灯光下。","一个男人站在堆积如山的机械零件之间。","他独眼冷漠，衣着粗糙，身上带着常年混迹灰色地带留下的锋利与戾气。","一双别具一格的鸳鸯眼让人难以忽视。","在外人眼中，独眼鹰是冷酷市侩的军火贩子，精于算计、杀伐果决、一身江湖戾气，在第八星系的灰色地带摸爬滚打半生，眼里只有利益，从无温情。","第八星系的地头蛇，还是本土产的大流氓。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["可无人知晓。","这个浑身是刺、四六不着的男人，将自己这辈子唯一的柔软、唯一的倾尽所有，全都给了一个来路禁忌的孩子。","【凯莱星·街区】","几个黑市人员站在角落，低声议论。","“那个孩子……”","“来路不明。”"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第一幕","text":["“听说身体有问题。”","一道高大的身影挡在少年面前。","独眼鹰抬眼。","鸳鸯眼里没有温度。","【独眼鹰】","“看够了吗？”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["他不会温柔安抚，不会柔声教导，不懂如何做一个合格的父亲。","有人暗中非议、窥探、欺凌陆必行。","他从不多言。","只是用最直接、最粗暴的方式摆平后患，让凯莱星上所有人不敢再妄动分毫。","【凯莱星·夜晚】","年幼的陆必行躺在床上。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第一幕","text":["脸色苍白。","呼吸不稳。","精神网异常波动。","陆必行因先天残缺常年病痛缠身、彻夜难安。","老军火贩子不擅长直白地表达关心。","于是转身离开。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["夜色中。","他穿过整座荒城。","走进凯莱星上的所有药铺。","寻找能够缓解少年痛苦的药物。","他一辈子嘴上刻薄、句句嫌弃。","行动却从未亏欠半分。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第一幕","text":["清晨。","独眼鹰推开工坊大门。","手中带着药剂。","少年仍不清醒。","他将药放下，没有叫醒他。","在人人自顾不暇的乱世。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第一幕","text":["他为多年前的一份情分","独独为陆必行挡住了整片荒芜的风霜。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["第二幕","【凯莱星·独眼鹰机甲维修工坊】","【时间：少年时期】","昏暗的工坊内。","老旧机械臂缓慢运转。","破损能源核心散落在地面。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第二幕","text":["淘汰的机甲零件堆积在墙角。","空气里弥漫着机油与金属混合的冷硬气息。","独眼鹰的机甲维修工坊，是陆必行童年最安稳的归宿。","年幼的陆必行坐在冰冷的金属地面上。","面前摆满了各种废旧机械零件。","他低着头，认真拆解、组合。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第二幕","text":["纤细的手指穿梭在复杂线路之间。","这里没有精致玩具，没有孩童嬉闹。","满地都是旁人弃如敝履的废旧机械臂、破损能源核心、淘汰的零碎配件。","空气里常年飘着机油与金属的冷硬气息。","幼年陆必行因女娲计划胚胎损伤与彩虹病毒后遗症，","天生精神网破碎、躯体孱弱、情绪极易失控。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["他比寻常孩子更脆弱、更焦躁。","时常无端失神、疲惫困顿。","被身体与生俱来的残缺反复折磨。","少年忽然停下动作。","手中的零件掉落。","短暂的精神涣散后，他闭上眼，缓慢调整呼吸。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["片刻后。","他重新拿起零件。","继续修复。","躁动不安的年纪。","他唯独在拆解机械、拼装零件时，才能获得片刻安宁。","他常常趴在冰冷的地面上。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["专注摆弄一堆废件。","不厌其烦地修复破损、重组结构。","独眼鹰站在工坊门口。","双手抱胸。","看着忙碌的少年。","“天天折腾这些破烂，能当饭吃？”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["陆必行没有抬头。","仍然认真调整线路。","“坏掉的东西，都可以修好的。”","工坊安静了一瞬。","这句天真的执念。","让久经世事的独眼鹰骤然沉默。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["无数破碎画面闪过。","战争。","废墟。","死亡。","被遗弃的人。","他见惯了乱世无法挽回的破碎。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第二幕","text":["见惯了人命如草芥、命运不可逆转。","早已不信“修复”与“重来”。","独眼鹰转身。","走向仓库。","沉重的金属箱落地。","一整箱保存完好的旧零件，被放在少年面前。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二幕","text":["“这些够你折腾了。”","他只是默然转身。","用独属于自己的方式纵容。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["第三幕","【凯莱星·机甲维修工坊】","【时间：数年后】","少年逐渐长大。","工坊里的机械零件越来越复杂。","桌面上摆满了他自己设计的改装图纸。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第三幕","text":["年岁渐长。","陆必行愈发清晰地感知到自己的“不同”。","公共终端前。","其他孩子顺利接入伊甸园系统。","陆必行伸手触碰。","屏幕却出现异常提示。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["精神链接失败。","无法完成公共精神网络接入。","与生俱来的精神网残缺无法遮掩。","他无法完整接入伊甸园系统。","时常突发疲惫、精神涣散。","偶尔情绪失控、心神空茫。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["这种根植于骨的残缺。","时刻提醒他——","他和这个世界格格不入。","夜晚。","陆必行站在工坊门口。","看着正在整理零件的独眼鹰。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["犹豫许久。","终于开口。","“我到底是什么人？”\n独眼鹰动作停了一瞬。","“为什么我和别人不一样？”","独眼鹰背对少年。","沉默许久。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["年少的他懵懂敏感。","终于察觉。","自己的异常并非偶然。","背后藏着养父绝口不提的秘密。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["第三幕","【凯莱星·机甲维修工坊】","夜色笼罩荒星。","工坊内只有机械运转的低鸣。","独眼鹰背对少年。","手中的零件停在半空。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第三幕","text":["他没有回答。","独眼鹰知晓所有血淋淋的真相。","胚胎辐射。","女娲实验。","陆信殉国。","母体惨死。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["以及那个他从未告诉过少年的事实——","这个孩子，本是一条本该夭折的残命。","尘封的记忆片段闪过。","辐射警报。","破碎的实验舱。","冰冷的数据记录。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["一个尚未成形的生命，在死亡边缘挣扎。","这些黑暗、沉重、足以压垮少年一生的宿命。","他全部独自封存。","独自背负。","少年站在灯光下。","等待答案。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["“你知道什么？”","独眼鹰低头。","许久没有开口。","他不敢说。","不愿说。","也不能说。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["如果他说出真相。","这个孩子会不会从此觉得自己不该存在？","会不会认为自己的生命，只是一场失败实验留下的残余？","独眼鹰转身。","拿起桌上的工具。","故作平静。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["“想那么多干什么。”","“你就是你。”","少年怔住。","这句话并不温柔。","甚至算不上一个合格的回答。","可是陆必行听懂了。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["他听懂了这份回避。","也听懂了这份保护。","陆必行低下头。","没有继续追问。","他隐约明白。","自己的来路藏着巨大的秘密。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["也隐约感知。","那秘密黑暗又刺骨。","可他不再执意逼问。","因为年少的他本能地懂得：","养父的隐瞒。","是一种庇护。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四幕","text":["第四幕","【凯莱星·夜晚】","荒星上空。","漫天星辰寂静无声。","远处废旧城市灯火稀疏。","独眼鹰工坊内。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第四幕","text":["灯光依旧亮着。","独眼鹰伏案处理繁杂的黑市交易。","屏幕上的星域数据不断跳动。","他的眉眼冷硬。","身上带着多年混迹乱世留下的锋利。","另一侧。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四幕","text":["陆必行趴在桌前。","认真摆弄机械零件。","两个人。","一个处理第八星系的灰色世界。","一个沉浸在自己的机械宇宙。","没有交流。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四幕","text":["却彼此陪伴。","凯莱星的深夜。","工坊灯火长明。","独眼鹰伏案处理繁杂的黑市交易、周旋星域利益，一身风霜戾气；","陆必行趴在另一侧桌前，摆弄零件、安静独处，一身纯粹柔软。","父子二人无言相伴。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第四幕","text":["没有温情对白。","没有亲昵相拥。","没有刻意的温情脉脉。","这是第八星系最粗粝、也最真挚的相处方式。","独眼鹰深夜替陆必行修理损坏的学习终端。","陆必行偷偷替独眼鹰整理凌乱的数据资料。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四幕","text":["独眼鹰用在第八星系半生杀伐。","为他隔绝世间污浊。","给他十几年干净安稳的少年时光。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四幕","text":["【玩家选择】","选择一：【继续接受独眼鹰保护】","【剧情】","陆必行逐渐读懂养父嘴硬心软的笨拙温柔。","他不再追问那些无法改变的过去。","选择坦然接受这份层层包裹的庇护。","【获得】","【亲情羁绊】","【解锁专属剧情】","一个不会说爱、却倾尽余生守护的父亲。","选择二：【追问自己的过去】","【剧情】","无法释怀自身与生俱来的残缺与异常。","心底的疑惑越来越深。","陆必行决定触碰那些被养父封存的秘密。","寻找自己的身世源头。","【获得】","【探索值】","【解锁支线】","女娲计划早期隐秘线索。","选择三：【走出凯莱星】","【剧情】","长久目睹第八星系世代沉沦。","看见无数人与自己一样，被困在荒芜与宿命之中。","陆必行第一次意识到：","自己想改变的不只是自己的命运。","【获得】","【理想值】","【解锁前置剧情】","星海学院建校初心完整铺垫。"],"choices":[{"title":"继续接受独眼鹰保护","key":"route_70_0"},{"title":"追问自己的过去","key":"route_70_1"},{"title":"走出凯莱星","key":"route_70_2"}],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第二章结尾","text":["第二章结尾","【凯莱星·深夜】","夜风穿过破旧的工坊。","吹动散落在地面的金属碎屑。","少年坐在桌前。","指尖轻轻抚过刚刚修复完成的机械零件。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第二章结尾","text":["荒星之外。","是无边沉寂的冷色星海。","少年指尖抚过被自己修复完整的机械零件。","心底生出绵长懵懂的思索。","破损的器械尚可重塑新生。","那生来残缺、被文明定义为异类、被世界遗弃的人……"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二章结尾","text":["是否也能拥有属于自己的位置？","没有答案。","此刻的他尚无答案。","却已经拥有了最珍贵的底气。","工坊灯光映在少年脸上。","另一边。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二章结尾","text":["独眼鹰背对他整理工具。","在整片星海皆荒芜、众生皆薄命的岁月里。","有人拼尽一身戾气。","半生罪孽。","只为留住他这一条残缺的命。","凯莱星这间破旧工坊的微光。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第二章结尾","text":["是陆必行一生善意、温柔与理想的起点。","也是他往后余生","敢与宿命抗衡的最初底气。","【第二章完成】","解锁章节：","《第三章》"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第二章结尾","text":["已获得羁绊：","【荒星庇护】","【父子羁绊】","已解锁属性：","亲情值\n探索值\n理想值"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三章：星海学院","text":["第三章：星海学院","章节时间：\n新星历270年","章节地点：\n第八星系·北京β星","章节主题：\n微光落地的理想","【第八星系·北京β星】","巨大的星球缓缓旋转。"],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第三章：星海学院","text":["城市灯光稀疏。","老旧建筑林立。","破损航道漂浮在星球轨道外围。","离开被庇护十几年的凯莱星，陆必行真正踏入第八星系最喧嚣、最芜杂的城市——北京β星。","城市街区。","流民穿梭。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第三章：星海学院","text":["黑市交易隐藏在阴暗角落。","没有身份登记的人群，沉默生活在文明边缘。","这里是荒星之中相对繁华的据点。","却依旧脱不开整片星域的底色：","秩序松散。","人心浮动。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三章：星海学院","text":["流民遍地。","被联盟放弃的边缘人聚集于此。","几个孩子站在街角。","没有完整身份信息。","无数空脑症患者、无籍孤儿、被主流文明淘汰的流浪者。","终其一生困在底层。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第三章：星海学院","text":["无人过问。","无人救赎。","陆必行站在人群之中。","看着这片熟悉又陌生的荒芜。","经历过凯莱星的荒芜。","看透第八星系根深蒂固的宿命困局。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第三章：星海学院","text":["少年多年蛰伏的理想终于落地。","陆必行倾尽自己多年积攒的所有身家。","变卖珍贵机甲。","耗尽科研积蓄。","废弃建筑被重新规划。","旧能源设备重新启动。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第三章：星海学院","text":["破败空间逐渐被改造成新的场所。","在北京β星的废墟与夹缝之中。","他撑起一所无人看好的学校——","地点解锁：","【星海学院】","这所学院从诞生之日起。"],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第三章：星海学院","text":["就站在世俗偏见的对立面。","它不收名门。","不收精英。","不收被文明筛选出来的“正常人”。","它只收被抛弃的人。","被定义残缺的人。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三章：星海学院","text":["被世人判定没有未来的人。","人群议论。","“一群残次品，再怎么教，也成不了气候。”","“这不是浪费资源吗？”","外界嘲讽不绝。","人人笃定他是白费力气。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三章：星海学院","text":["陆必行站在学院门口。","看着逐渐亮起的灯光。","面对整片星域的质疑。","陆必行始终平静坚定。","他见过残缺的自己。","见过被遗弃的同类。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三章：星海学院","text":["见过无人兜底的荒芜。","“人的价值，从不由出身定义。”","“也不由残缺判定。”","“只由自己创造。”","学院大门开启。","黄静姝、薄荷、怀特、斗鸡等第一批绝境里的孩子成了星海学院的学生。"],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第三章：星海学院","text":["【角色加入】","黄静姝","薄荷","怀特","斗鸡","他们带着孤僻、叛逆、自卑与满身伤痕。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三章：星海学院","text":["汇聚在这所破败却唯一愿意接纳他们的学院里。","课堂。","陆必行站在讲台前。","学生们安静听课。","陆必行以最大的温柔与包容接纳所有人的不同。","因材施教。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三章：星海学院","text":["耐心引导。","在人人踩踏弱者的第八星系。","他第一次为“残缺者”立起了一方可以堂堂正正活着、堂堂正正求学的天地。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三章：星海学院","text":["【星海讲堂已解锁】","点击下方按钮，阅读《星海讲堂·陆校长开学致辞》。"],"choices":[],"plugin":{"title":"星海讲堂·陆校长开学致辞","label":"星海讲堂","content":["欢迎各位来到星海学院，欢迎踏足这片第八星系的荒原学堂。我知道诸位来路坎坷，不少人早早辍学、揣着假证书，旁人总说这里尽是朽木、粪土之墙，可我始终觉得，辍学未必是自愿，困顿里未必藏不住火种。古谚有言，只有通往地狱的路，才铺满善意的鲜花，困境本就是逐梦必经的长路。","有人问学机甲、学信息能赚大钱，这话不假，顶尖机甲设计师会被各方争抢，可贫穷比愚蠢致死率高，活着从来不止追逐银钱。伊甸园能无痛灌输知识，可第八星系的我们没这份优待，只能一字一句啃书本，一步一难往前走。","我希望诸位来日身在风口浪尖，别得意忘形；沉入水下暗流时，绝不与泥沙俱下，学院为你们灵魂筑下基石。最后，请所有人牢牢记住：比金钱更珍贵是知识，比知识更珍贵的是无休止的好奇心，而比好奇心更珍贵的，是我们头上的星空。","这六百万造价的穹顶星空，不是装饰，是我们被困荒漠仍不肯舍弃的理想。淤泥深处尚可拾得星光，残次品照样能奔赴整片星海。"]},"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第四章：","text":["第四章：","《漂流在星海的人》","时间","新星历270年后。","地点","第八星系。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章：","text":["主要人物","陆必行","林静恒","独眼鹰（背景出现）","湛卢（隐藏）"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["【章节开始】","第八星系。","这里距离联盟中心很远。","没有沃托的政治中心。","也没有白银要塞曾经的辉煌。","这里有自己的规则。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"章节开始","text":["资源。","交易。","势力。","以及无数想在星海里寻找未来的人。","陆必行驾驶着自己的机甲。","穿行在第八星系边缘。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"章节开始","text":["这台机甲不是联盟军方制造。","也不是任何军火商提供的成品。","它来自陆必行自己的设计。","从能源系统到控制程序。","都是他一点点研究出来的成果。","在第八星系。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"章节开始","text":["独眼鹰是一个无法忽视的人物。","他控制着大量资源和交易渠道。","也是陆必行成长过程中最重要的人。","独眼鹰把陆必行养大。","教会他如何在第八星系生存。","教会他面对危险。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["也教会他这个地方真正的规则。","只是。","他们对于未来的看法并不相同。","独眼鹰：","“好儿子”","“不是所有问题，都能靠知识解决。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["陆必行叹了口气：","“老陆”","“如果没人相信知识。”","“那这个地方永远不会改变。”","一个是现实世界里摸爬滚打的人。","一个是始终相信未来的人。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["【发现生态舱】","一次独自探索中。","陆必行驾驶机甲离开既定航线。","进入一片无人区域。","雷达突然捕捉到异常信号。","不是通讯。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"章节开始","text":["不是能源波动。","而是一组微弱的生命维持数据。","【选择】","选择一：","「靠近信号源」","陆必行改变航向。","未知区域意味着危险。","但是。","如果那里真的还有一个活着的人。","那么放弃，就意味着死亡。","属性：","文明值+10","选择二：","「分析生态舱数据」","陆必行没有立即靠近。","他开启扫描系统。","分析生态舱结构。","确认能源状态。","寻找最安全的救援方式。","属性：","科研值+10","选择三：","「返回基地寻找支援」","未知的危险无法预测。","陆必行知道。","一次错误的决定。","可能让救援变成新的事故。","属性：","战略值+5","【固定剧情】","最终。","陆必行还是回到了那个信号的位置。","因为他始终无法忽视一个事实。","那里。","可能还有一个人在等待。","漂浮在宇宙中的生态舱已经损坏。","外部装甲留下长期漂流的痕迹。","内部系统却仍然维持着最低运行状态。","陆必行打开扫描。","发现里面有一个生命体征。","很微弱。","但存在。","他开始检查生态舱。","能源接口。","生命维持系统。","休眠程序。","每一步都必须谨慎。","因为里面的人已经沉睡太久。","任何错误操作。","都可能造成无法挽回的结果。","一天过去。","生态舱没有任何变化。","两天过去。","里面的人依旧沉睡。","陆必行没有离开。","他继续修复设备。","继续观察生命数据。","等待那个不知道名字的人醒来。","他不知道。","这个人曾经是谁。"],"choices":[{"title":"选择一","key":"route_101_0"},{"title":"选择二","key":"route_101_1"},{"title":"选择三","key":"route_101_2"}],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["不知道这个人经历过什么。","更不知道。","这个沉睡的人。","曾经站在联盟最高的位置。","很久以后。","生态舱终于出现变化。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"章节开始","text":["生命维持系统重新调整。","沉睡状态解除。","那个在星海中漂流许久的人。","终于睁开眼睛。","陌生环境。","陌生设备。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["陌生的人。","林静恒醒来的第一时间。","不是询问过去。","而是判断现在。","位置。","危险。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["身份。","所有信息在极短时间内重新整理。","陆必行：","“你醒了。”","“我叫陆必行。”","林静恒："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["“这里是什么地方？”","陆必行：","“第八星系。”","生态舱内部。","一个沉默许久的人工智能程序重新启动。","它安静等待着。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["等待自己的主人重新回到这个世界。","林静恒抬眼望向眼前满怀热忱的年轻男人，","灰眸中情绪淡不可辨。","他蛰伏五年、步步筹谋的所有计划里，","从未预料会在这片荒芜星域，","撞上这样一个意外的人。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"章节开始","text":["舷窗外无边黑暗星海翻涌，","陆必行望着漫天碎石，","心底那句感慨轻轻落了下来：","“旁人都说这里尽是烂泥，可我总觉得，","淤泥深处，总能捡到星星。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四章结束","text":["第四章结束","解锁：","【生态舱档案】","【陆必行初遇】","【未知身份】"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第五章 情愫","text":["第五章 情愫","（新星历275，十六年大战爆发前）","破酒馆暖光压得很低，陆必早精心收拾出一身随性松弛的模样，披着外套斜倚吧台，刻意调出一层人工柔光滤镜衬自己，等候黑洞实际掌权人四哥。","五年前他在无人星带捞起漂流生态舱，救下沉睡的那个人，五年相处，两人始终隔着一层恰到好处的分寸，旁人眼里只是八星系一对交情尚可的熟人，唯有湛卢的数据，藏着林独一份的耐心。","桌角摆着毒巢人贩子“蜘蛛”上缴的生物芯片，屏幕弹出三道科研抉择弹窗，是陆必行眼下的难题：","【选项一：优先拆解芯片神经模块，科研值+12，消耗三周实验耗材】"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第五章 情愫","text":["【选项二：先推演人体改造风险，安全阈值拉满，耗时翻倍】","【选项三：向林申领全额经费，解锁专属实验室权限】","陆指尖悬在光屏，苦笑坦言学院早已捉襟见肘，机甲教具、实验试剂全欠着缺口。","林静恒指尖夹烟，眉眼覆着一层化不开的冷，只淡淡一句“找湛卢核算”，轻飘飘替他兜底。","陆必行当即趁热打铁，盛情递出开学典礼VIP邀约，林眼皮一掀，吐出利落一个“滚”。","等陆必行拎着芯片样本兴冲冲离开，酒馆只剩一人一人工智能。湛卢平稳播报数据分析：“先生，您对陆校长包容度远高于该星系的其他人，属于特殊情绪波动。”林静恒擦着玻璃杯，不置可否，眼底却掠过一点极淡、藏不住的笑意，又吩咐湛卢次日备好一身干净外套。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第五章 情愫","text":["次日星海学院礼堂活像失控游戏副本，游戏化乱象遍地：学生私改礼堂音响刷屏、自制激光枪斗殴、退学人数远超报到生，三层院长集体递交辞呈。","穹顶六百万造价仿真星河下，陆必行站高台演讲，刚说到“比星空更珍贵是好奇心”，余光扫见VIP通道走来一行人，脚步瞬间顿，整段演讲稿早忘得一干二净。","林静恒身披长大衣，气场压满全场，只远远同他对视一眼，便寻角落落座，安静听完整场鸡飞狗跳的宣讲。散场后悄无声息离场，连一句寒暄都不留。","陆必行望着空座位，心底漫开一层说不清的怅然。","晚间陆必行再赴破酒馆，林已将缴获的单人机甲赠予学院，供学生实操教学。两人对着芯片细聊伊甸园仿造技术，陆必行滔滔不绝，眼里盛着八星系独有的热忱，林静恒垂眸静听，极少插话，却字字记在心底。","旁人眼里他是心狠手辣、不近人情的黑洞四哥，唯独对着满脑子办学理想的陆必行，收敛所有尖刺。"],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第五章 情愫","text":["他从不会直白表露心意，只默默出钱、送机甲、撑场面，用沉默的托举回应少年滚烫的理想。","淤泥般荒芜的第八星系，陆必行是撞进他深渊里的星火，而林静恒，是独独愿意托住他漫天空想的靠山，这份偏心，在战火与分离到来之前，安静蛰伏在破酒馆的朗姆酒香里。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第六章：启明星的黎明与离别","text":["第六章：启明星的黎明与离别","【章节开场】","毒巢空间站的残骸漂浮在第八星系边缘深空，那些靠生物芯片操控孩童的人体实验卷宗，经由湛卢全部解密投影在银河城指挥大厅。","这场据点覆灭没有带来真正和平——造神芯片的复刻技术被多方势力截获，有人意图永久销毁，有人想改良牟利，还有人妄图复刻“完美人类”，借芯片奴役众生。","湛卢人形伫立，碧绿眼瞳铺满全域红色警报，语调平稳，不带半分情绪起伏：","“先生，全域溯源完成。造神芯片流通分三股势力：自由军团地下军火商、伊甸园管委会高层私库、林静姝专属加密通讯频道，匹配度99.7%，相关通讯记录已最高权限加密留存。”"],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第六章：启明星的黎明与离别","text":["林静恒指尖无意识摩挲吧台冷金属台面，眼底没有暴怒，只有一层沉郁疲惫。五年隐姓埋名蛰伏第八星系，本以为暂时隔绝沃托的权力泥潭，却不知祸根早已渗透身边。","“全部封存，禁止外流。”他声线压得很低，听不出波澜。","陆必行倚在操作台边，指尖无意识摩挲胸口——当年女娲计划刻在他骨血的烙印让他对这类控制类技术本能憎恶，温和笑意尽数褪去，只剩沉凝冷意。","一旁独眼鹰斜倚门框，鸳鸯眼沉沉扫过星图，陆信旧部的积怨翻涌眼底。他久居第八星系，极少接触沃托上层人物，只从零散情报里听过管委会那群掌权者的虚伪做派，分不清谁是格登，只知道沃托高层靠着伊甸网络玩弄权术，当年便是这群人联手构陷陆信。他看向林静恒，眼底混杂感激与隔阂：感激他守住八星系，又记恨联盟整体卸磨杀陆信，复杂矛盾一览无余。","独眼鹰闷声开口，语气裹着经年火气：“沃托那帮坐享其成的权贵，隔着几大星系都能把手伸过来折腾人命，当年陆将军就是栽在他们这套阴私算计里。”","【剧情推进｜彩虹瘟疫，淤泥里长出星火】"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第六章：启明星的黎明与离别","text":["造神芯片的追查尚未落地，彩虹病毒骤然席卷七大星系。依托伊甸园精神网极速扩散，被联盟民众奉为救赎的精神网络瞬间沦为囚笼，无数人陷入幻觉、自残与集体暴乱，所有人第一次认清伊甸园暗藏的枷锁。","唯有从未完整接入伊甸园的第八星系守住秩序。这里世代被联盟抛弃，人人习惯失去，反而最懂如何互相托举。","独眼鹰掏空早年囤积的抗病毒原料，打通所有地下航道跨行星调配物资；林静恒不带白银武装，孤身穿行疫区搜集紧缺抑制剂；陆必行改造星海学院实验室，拆解简易检测仪器分发给各个聚居点，空脑症学生全员编入防疫小队——空脑症先天隔绝伊甸信号，是天然的防疫屏障。","漫长隔离期结束，启明星重建工程正式落地，荒芜戈壁上拔起银河城。星海学院新校区落成，空脑症收容中心、机甲工坊、信息研究院同步完工。陆必行亲自封存全部女娲人体改造资料，立下铁律：","“技术可以造器械、拓航道、医治病痛，但永远不能用来篡改人的意志，更不该定义谁是‘残次品’。”","入夜，整座银河城灯火顺着人工航道绵延至星海，曾经寸草不生的荒芜星球，第一次生出人间烟火。"],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第六章：启明星的黎明与离别","text":["陆必行凭栏吹风，晚风掀松他肩头外套，目光落向下方成片民居，语气轻得裹着陈年酸涩：","“从前北京β星的人，连做梦都不敢做得圆满，梦做多了，反倒要遭旁人取笑。久而久之，很多人干脆不再抱有期待，反正无论憧憬什么，最后都是一场空。”","林静恒站在他身侧，常年覆在周身的杀伐冷意淡去几分，灰色眼眸浸着整片城市灯火，沉默良久才开口，声音轻得会被晚风卷走：","“你建星海学院、重建这座城，只为争一口气？”","陆必行偏过头，眼底盛着细碎星光，惯有的玩笑腔调压下去，只剩坦荡坚定：","“不是争输赢。我只是想告诉那些空脑症、流离的孩子，他们生来不该被贴上残次品的标签，人生不必由别人提前写好结局。”"],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第六章：启明星的黎明与离别","text":["林静静静望着他，心底积压的负重悄悄松动。他半生扛着陆信遗恨、联盟背叛、与亲妹反目的三重枷锁，厮杀半生只懂以利刃止战；直到遇见陆必行才看清，原来守护也可以是温柔地为弱者撑起一片容身之地。","陆必行轻轻侧靠近半步，气息漫过晚风，带着一点试探的软意：","“等一切尘埃落定，你愿意留在启明星，不用再回那些刀光剑影的地方吗？”","林静恒喉间微紧，顿住许久没有作答。他心里藏着不敢宣的贪恋，却也清楚沃托、白银要塞的血海他终究避不开。","湛卢立于观景台暗处后台同步情绪分析，无外人听见的机械音单独录入存档：","【数据判定：先生心率小幅上浮，对陆必行信任度提升；陆必行情感倾向偏向长期共处羁绊，解锁前置线索「星海星火」】"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第六章：启明星的黎明与离别","text":["【互动选择一（前置路线倾向判定，影响双人羁绊解锁）】","选择一：【陪同陆必行去星海学院】","触发专属剧情：走访空脑症宿舍、机甲实训教室，旁听陆必行给孩子们讲课，完整窥见他“以文明容纳残缺”的核心理想，亲眼看见他将女娲计划的伤痛转化为庇护众生的温柔。","羁绊变化：陆必行信任度大幅提升，永久解锁双人温柔对话支线，解锁羁绊【星海星火】","选择二：【核查芯片与域外暗线】","触发专属剧情：跟随林遍历疫区据点、审问毒巢俘虏，见证他独自压下杀戮，尽力给普通人留生路的隐忍柔软，读懂他背负全联盟罪孽的将帅宿命。林静恒会顺带提起沃托管委会、林静姝布局的内情，提及沃托高层的一系列阴谋，仅说出“秘书长”头衔，不提及格登姓名。","羁绊变化：林静恒坦诚度提升，解锁隐藏心理描写支线，解锁羁绊【白银孤刃】","【剧情推进二｜黎明裂痕，战火将至】","启明星的安稳只是短暂幻象。林静姝暗中扶持自由军团批量改造芯片战士，伊甸园管委会借灾后管控强行植入民众精神调控模块，两方势力互相利用、蚕食星域权力，全面内战的警报拉响。","湛卢将全域战力推演投射在指挥大屏，冰冷数据刺破所有人的侥幸：","“综合军备、改造人储备、伊甸网络控制权测算，半年内八大星系全面内战爆发概率87.4%。”","陆必行指尖轻叩操作台，眼底笑意彻底敛去：","“永远有人自认手握最优解，总想着替全人类筛选‘完美人生’。”","林静恒侧眸看向他，眉峰微沉：","“你不认同这套逻辑？”","陆必行抬眼，语气温和却字字铿锵：","“绝不。人类的珍贵从来不是毫无瑕疵，恰恰在于我们会犯错、会煎熬，却依旧拥有自主选择人生的权利。技术是拐杖，不是锁住灵魂的牢笼。”","这是二人最深的共识，也是他们终将分赴两条道路的根源：一人愿以文明生根，一人必须执刃挡祸。","独眼鹰推门而入，手里攥着跨星域急报，只看懂“沃托高层内乱、白银要塞自爆”关键信息，不懂其中高层具体人名，语气沉重：","“沃托那边彻底乱了，当年陆将军拼下来的防线全塌了，那些躲在伊甸网络后面的权贵，终于闹到自相残杀。”","选择一：【扎根启明星】","核心立场：守住星海学院与八星系自治秩序，以教育与民生庇护所有被抛弃的人，拒绝以暴力循环对抗暴政。","解锁主线：《新星海时代》","角色倾向：温柔负重的文明守路人，解锁陆必行全部内心独白与温柔向单人剧情","选择二：【收拢白银十卫】","核心立场：唯有足够强悍的武装才能撕碎芯片奴役与伊甸管控，护住后方仅存的人间烟火。","解锁主线：《白银守护》","林静恒顺着陆必行的心意，默许他在机甲舱添置绿植加湿器，","时常让湛卢前往学院辅助授课，甚至暂时搁置筹谋多年的布局，","陪着他一点点完善学堂","在外人人都畏惧杀伐果决的黑洞四哥，","面对陆必行会卸下一身尖刺，","实打实的付出默默托举对方旁人眼里荒唐的理想","后来，","战火尚且蛰伏在遥远星海，","彩虹病毒、域外海盗、联盟阴霾层层笼罩第八星系，","淤泥遍地的荒芜星域里，","怀揣理想的少年与满身旧伤的上将彼此牵绊，","未曾宣之于口的缱绻情愫，","藏在实验试剂、废弃机甲与漫天星河之间，","安静等候那场遥遥无期的长久别离。","仿佛理想主义化身的少年用纯粹与特别，","在岁月里雕刻着腥风血雨里脱身的将军","“我不用你承诺什么，但无论多远，记得回来。”","【剧情推进三｜上将归位，一身枷锁重扛】","沃托动乱、白银要塞化为焦土的跨星域消息传来，沉寂五年的白银十卫加密通讯频道全线重启，散落各地旧部等候统帅归位。","湛卢投影联盟上将全套权限档案，冷白肩章虚影悬在二人之间：","“先生，联盟军委遗留指令全部解锁，您的上将身份正式恢复，全域刺杀目标置顶。陆校长无随军作战规划，将长期留守启明星。”","林静恒指尖虚碰虚拟肩章，动作滞涩一瞬，五年四哥的闲散伪装彻底剥落，肩上重新扛起整片星海的生死重担。","“我知道。”他低声回应，语气里听不出波澜，只有湛卢能捕捉他转瞬低落的情绪。","湛卢如实上报数据分析：“后台情绪监测显示，您潜意识极度希望带陆校长同行，但理智判定启明星无人镇守，不能托付。”","林静恒没有否认，只抬眼望向窗外银河城灯火，轻声自语，只有自己能听见：","“我不想让他沾半点硝烟。”","一旁独眼鹰靠墙壁静静听完全部对话，鸳鸯眼沉沉打量林。他不懂沃托高层的派系厮杀细节，只清楚眼下席卷八大星系的动荡需要有人挡在前面，终究只是闷哼一声，不再出言阻拦。","【剧情推进四｜星港离别】","启明星主星港，白银巨型舰队整齐列阵，跃迁引擎预热，冷金属光铺满整片停机坪，凌晨黎明薄雾裹着刺骨深空寒气。","陆必行独自赶来送行——他太懂林肩上背负的责任，所以不想用私情困住对方。","二人隔着数步距离，身后是万家灯火，前方是无边战乱星海。","陆必行先开口，照旧用轻松调侃藏起心底酸涩：","“别人出征好歹有个准信，到你这里，从来说不清什么时候回。”"],"choices":[{"title":"陪同陆必行去星海学院","key":"route_119_0"},{"title":"核查芯片与域外暗线","key":"route_119_1"},{"title":"扎根启明星","key":"route_119_2"},{"title":"收拢白银十卫","key":"route_119_3"}],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第六章：启明星的黎明与离别","text":["林静恒望向他，常年覆在眉眼的寒霜软下一层，声音很低，只有两人能听清：","“我给不出确切归期，乱世没有人能打包票。”","陆必行收敛玩笑，往前半步，距离分寸刚好不逾矩，目光牢牢锁在林脸上，轻声唤那个只属于他的称呼：","“林。”","林静恒应声抬眼。","陆必行字字清晰，没有哭闹纠缠，一句托付即是全部心意，复刻原文内核："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第六章：启明星的黎明与离别","text":["“不用硬撑着所有人的安危不顾自己。启明星我守着，我等你回来。”","林静恒喉间微涩，征战半生，千万将士、整片联盟他都扛过，唯独眼前这个人，是他唯一不敢赌的软肋。他没有多余抒情，只道一句托付，拆分两层重量：","“启明星交给你。”","陆必行挑眉，带一点浅淡笑意，冲淡离别压抑：","“联盟上将的军令？”","林静恒深深凝住他，灰色眼底翻涌从未外露的信赖与藏了五年牵挂，一字一顿："],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第六章：启明星的黎明与离别","text":["“是命令。”","星港引擎低鸣盖住细碎风声，后半句轻得像心底私语，他唯一一次卸下铠甲的真心话：","“也是我的托付。”","他征战半生，守护过沃托、守护过万千星域众生，却从没有一处人间、一个人值得他交付全部退路。唯有启明星，唯有陆必行，是他跨越星海也要奔赴的归途。"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第六章：启明星的黎明与离别","text":["【剧情小卡片已解锁】","点击下方按钮，阅读《十六年》。"],"choices":[],"plugin":{"title":"十六年","label":"剧情小卡片","content":["他在第七星系的战火中失了踪影。林静恒最后的消息，是图兰报告里一串冰冷的坐标——跃迁点爆炸，指挥舰解体，白银十卫几乎尽数折损其中。陆必行盯着通讯屏幕上那条终于归于静默的信号线，觉得自己也随那场爆炸碎在了星海尽头。","此后十六年，第八星系成了一个孤岛。","陆必行把破碎的自己一片一片捡回来，拼成一个还能站立的人。他在凌晨四点看军工厂的报表，在午夜的办公室里批阅重建规划，在所有能挤出的时间里，修复那个再也等不到主人的人工智能。湛卢的机械手在实验室里一次次亮起又熄灭，像一只固执的萤火，照着一个人不肯熄灭的念想。","他偶尔会在某个极其疲惫的深夜，恍惚间听见走廊尽头有熟悉的脚步声，回头时只有自己拉长的影子。","而那个人其实还活着。","林静恒被林静姝困在一个与世隔绝的小行星上，在生态舱里昏睡了整整两年。他的意识像一缕将断未断的丝线，悬在生与死的罅隙里，每一次试图挣脱都撞上冰冷的屏障。他尝试了两千余次的越狱，犹如冷静而固执的困兽。","他不说话，不挣扎，不向任何人示弱，只用自己的眼睛一点一点地丈量这方牢笼的每一道裂缝。又在某个恒星风暴过境的深夜，借着那片短暂紊乱的能量场，生生从那副生不如死的躯体里撕出一条生路。","他花了十六年，从灰烬里爬回人间。","而陆必行，用了同样的十六年，让自己长成能接住这个人的模样。","当虫洞再次撕裂时空，当那架破旧的小机甲终于穿过玫瑰之心的乱流出现在启明星的天际线上时，陆必行没有哭。他只是站在机甲站的监控镜头前，看着那个瘦得几乎脱了形的人，一步一步走下舷梯。","像等了一辈子的月亮终于回到海上，他不敢大声呼吸，怕惊散了这漫长的长夜。","陆必行走进指挥中心时，那针舒缓剂六号的血药浓度刚好攀上峰值。他的步伐平稳，脊背笔直，同每一个向他汇报的卫兵点头致意，声音里听不出半分波澜。只有林静恒第一眼就看见了他微微发红的眼白——那是药物强行压下某种激烈情绪留下的痕迹。","两人之间隔着半个指挥大厅。","满室的人来人往忽然褪了色。陆必行把目光钉在全息星图上，手指落在某一处坐标上停了半秒，又若无其事地移到下一处。他没有回头，没有失态，甚至没有让呼吸乱上一拍。","林静恒靠在门框边，瘦得肩骨支棱着衬衣，脸上还带着久不见光的苍白。他也没有动。他隔着半个大厅看那个人的背影，看到陆必行的站姿变了——以前那个人站着总要歪一点，肩是松的，像随时准备转身跟人说笑；现在他站得笔直，每一块骨头都卡在应该在的位置上。","这十六年，陆必行学会了把自己装进一副严丝合缝的壳里。","然后陆必行转过身来，隔着半个大厅对他笑了一下。那个笑容浅得几乎称不上笑，只是唇角松了松，眼里却一点波纹也没有，像一面快裂了却还在勉力撑着的冰。","林静恒忽然觉得胸口那根肋骨疼得有点过分——也许是当年在太空监狱里断过的那一根。他从不习惯在人前示弱，于是他挑了挑眉，用那种漫不经心的、欠揍的腔调开了口：","“演得挺像。”他说，“跟谁学的？”","陆必行的嘴角又往上提了一点点，幅度小得几乎让人疑心是错觉，像是他整个人已经被那针舒缓剂六号冻住了，只剩这一丝薄薄的弧度还在勉强替他活着。他没有回答这句话，只是用一种极轻极静的语气说：“统帅，欢迎回来。”声音平得像在念一份军需报表，十六年的等待压进去，竟连一个颤音也没剩。","林静恒垂下眼。他想：原来被人用自己惯用的方式对待，是这种滋味。他花了半辈子用这套把戏把所有人推远，现在终于有人学会了，连本带利地还回来。而他无话可说，因为是他教的。","跃迁点的感觉还在身上，十六年的爱人生离死别后的重逢。","至此","黯淡了十六年的星星","于淤泥中间熠熠发光"]},"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第七章：玫瑰之心","text":["第七章：玫瑰之心"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第一幕","text":["第一幕","【白银旗舰指挥大厅】","整片星域星图铺满灰红交错的警报色块，林静姝改造人军团像蜂群填满跃迁航道。鸦片芯片植入颅腔，抹除恐惧、痛感、自我意识，敌军机甲驾驶员只剩单一杀戮指令，常规编队接触片刻便全线溃散，残骸漂浮在无光深空，像一滩滩失去魂魄的躯壳。","湛卢人形立在指挥台侧，碧绿光屏滚动冰冷演算数据，语调平直，不带半分人为情绪，只有数据陈述：","“先生，全域战损实时更新。改造单位无上限持续增援，常规正面围剿战术综合胜率27.3%。鸦片芯片可强行改写人类精神阈值，普通驾驶员接入战场三小时，自我认知会彻底消融。”","指挥厅内一片死寂。图兰指尖死死扣住操作台边缘，眼底压着一层不忍，望着星图上密密麻麻的红标，低声开口："],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第一幕","text":["“我们要打的从来不是敌军，是一群活生生被人剥走‘自己’的普通人。”","林静恒垂眼落在星图上，指尖无意识摩挲肩章磨旧的纹路。十六年隐姓埋名躲在第八星系，以为能暂时躲开联盟积压的所有祸根，到头来陆信的旧仇、林家兄妹的隔阂、全星系人的苦难，尽数堆在他面前。他说话声音很轻，没有激昂控诉，只一句冷透的断论：","“她造的从不是兵器，是一群失去选择权的人。”"],"choices":[],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第一幕","text":["【玩家前置双线互动选择（绑定羁绊、专属战场剧情解锁，游戏机制完整保留）】","选择一：【白银分割围剿】","路线归属：白银守护主线","羁绊变化：\n林静恒信任度大幅上涨，白银十卫全员好感解锁，解锁人物隐藏过往回忆","专属触发剧情：","跟随林静恒制定跃迁点封锁战术。战前他会先划出大片平民与俘虏撤离空域，优先规划保全普通人退路，再谈清缴敌军。能窥见他骨子里厌弃杀戮，却不得不扛起屠刀的挣扎。","专属解锁线索：","白银要塞遗留重型屏蔽武器档案、改造芯片物理爆破参数。","选择二：【研究芯片先天弱点】","路线归属：文明破解主线","羁绊变化：\n陆必行双向信任同步提升，湛卢解锁哈登博士加密底层实验卷宗","专属触发剧情：","湛卢搭建加密跨星通讯，实时同步银河城实验室数据。远程旁观陆必行带领空脑学生推演芯片缺陷，知晓空脑症先天隔绝鸦片精神干扰这一破局关键。","专属解锁线索：","女娲计划原始人体实验记录、空脑精神屏障完整理论。"],"choices":[{"title":"白银分割围剿","key":"route_127_0"},{"title":"研究芯片先天弱点","key":"route_127_1"}],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第二幕","text":["第二幕","【星海学院地下档案室，遮光光屏映满冷白字迹】","陆必行调取哈登遗留最高权限封存档案，层层拨开林静姝从乌兰天才滑向深渊的整条轨迹。少时与兄长被迫拆分，常年困在伊甸园情绪管控下，自幼认定痛苦、软弱、残缺都是文明累赘，最终借鸦片芯片妄图一刀切，抹掉所有人性里的“瑕疵”。","独眼鹰守在密室门外，鸳鸯眼沉得像积了百年乌云。作为陆信旧人，他比谁都清楚联盟上层如何磋磨林家姐弟，一声闷叹压在喉间，没进来打扰室内人。","光屏上少年时期的林静姝眉眼尚干净，陆必行长久静立，半晌才低声开口，语气里没有纯粹憎恶，只剩一层绵长惋惜：","“她分得清芯片会伤人，只是笃定只要目标足够宏大，所有个体的悲欢、苦难，都可以被牺牲。”"],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第二幕","text":["湛卢同步调取跨星域情报比对，光屏跳出双方通讯溯源记录：","“数据匹配完成，林静姝所有武装布局依托鸦片芯片扩张，但核心诉求并非占领星系，而是彻底剔除人类与生俱来的不完美。”","陆必行垂眸，脑海里浮现星港别离那日林静恒沉默的侧脸。他终于懂了对方长久回避这个名字的缘由——那不是无关仇敌，是血脉至亲一步步走到对立面，是跨越十六年解不开的遗憾与两难。","晚风从通风口溜进档案室，掀动一页泛黄的实验纸，纸上写着哈登那句批注：人之所以为人，在于敢接纳自己的裂痕。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第三幕","text":["第三幕","【玫瑰之心外围中央军主舰指挥舱】","伊甸园管委会借精神网络钳制全民情绪，林静姝在外以芯片军团蚕食星域，战火撕裂八大星系。伍尔夫手握联盟仅存完整中央机甲军团，站在两条歧路中间，抛出一套折中制衡方案。","老元帅一身落满硝烟的旧军装，眼底藏着半生疲惫，语气沉缓，无半分空想的狂热：","“人类所有战乱，根源都出自欲望、恐惧、爱恨这类非理性情绪。以军政体系约束伊甸权限、限制芯片流通，人为抹平极端矛盾，便能换来长久无硝烟的平稳。”","光屏铺开全域模拟推演，画面里众生无悲无怒，没有冲突，也没有心动与遗憾，是一座规整却死寂的人造乌托邦。"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第三幕","text":["陆必行远程接入跨星通讯，没有立刻反驳，安静听完整套推演，停顿片刻才缓缓开口，语调温和却立场坚硬，字字扣着“残次品”的底色：","“倘若世界再也容不下犯错、煎熬、心动这些不完美，那活在里面的，还能叫做人吗。”","伍尔夫眉头微蹙，语气带着历经战乱的固执：","“稳定是文明存续第一要务。”","“稳定不该以剥夺选择为代价。”","陆必行抬眼，脑海里掠过星海学院一屋子空脑孩童："],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第三幕","text":["“文明存续的根基从不是标准化的平静，是人有权利走一条属于自己的路，哪怕这条路布满差错。”","【关键主线锁定抉择】","选择A：【接纳均衡管控秩序】","解锁主线：机械均衡线","路线后果：","第八星系纳入联盟统一管控，星海自由教学权受限，空脑、残次品依旧会被系统标记为不稳定隐患；解锁伍尔夫晚年自我怀疑私密手记。","选择B：【死守人类自主选择权】","解锁主线：星火传承线","路线后果：","联合空脑军团与白银援军缔结跨星系同盟，完整解锁哈登全套制衡理论；为隐藏结局必备前置条件。"],"choices":[{"title":"接纳均衡管控秩序","key":"route_132_0"},{"title":"死守人类自主选择权","key":"route_132_1"}],"background":"背景图片/沃托白塔-政治场景.png"},{"chapter":"第四幕","text":["第四幕","【十六年牵挂】","玫瑰之心虫洞引力持续干扰信号，两道跨星域通讯窗口艰难同步亮起。","一侧是白银旗舰满是炮火划痕的指挥台，林静恒一身征尘，眼底藏着十六年遥遥相隔的忐忑；一侧是银河城观景台，陆必行身后绵延整片城市灯火。相隔亿万光年，理念相悖之下，藏着没说出口的惦念，对话无直白告白，所有情绪压在停顿与眼底。","陆必行先开口，惯有的松弛调侃压下心底沉甸甸的忧虑，轻得像一阵晚风：","“你计划摧毁全部鸦片芯片生产基地，连那些本可用来修复神经损伤的改良样本，也一并销毁？”"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第四幕","text":["林静恒指尖无意识擦过光屏上陆必行模糊轮廓，沉默许久，声线裹着十六年积压的亏欠，低沉沙哑：","“只要技术的前提是夺走人的自我，便没有留存的资格。”","陆必行低头浅浅笑了一下，笑意浮不到眼底，藏着多年了然：","“从前我总觉得，你太过信奉兵刃能了结一切纷乱。”","林静恒抬眼，穿过漫天星尘望向屏幕里的人：","“如今怎么看？”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第四幕","text":["“如今懂了。”","陆必行声音放轻，隔着星尘传递：","“你从不是嗜杀，只是比任何人都恐惧，有人擅自替旁人敲定一生的路。”","林静恒没有否认，长久静默。十六年前被迫凭空消失，十六年后战火再一次把二人拆分，他心里藏着一句不敢出口的怕——怕此战过后，又是十数年遥遥相隔。","湛卢后台同步情绪记录，光屏小字无声滚动：","双向羁绊数值大幅上涨，解锁隐藏结局前置判定项。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第五幕","text":["第五幕","【玫瑰之心虫洞】","玫瑰之心天然巨型虫洞横亘在八大星系航道中央。","这里曾是连接无数星域的交通枢纽，如今却成为战争最残酷的绞杀场。","折断的机甲残骸漂浮在虫洞边缘，废弃芯片碎片随着引力乱流缓慢旋转，失去控制的能源光束不断撕裂黑暗深空。","三方势力在此汇聚。"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第五幕","text":["一方，是以林静姝为核心的改造人军团。","一方，是以林静恒率领的白银十卫。","另一方，是仍在观望中的中央军。","主舰静静悬浮在虫洞最深处。","指挥舱内没有战前紧张的喧嚣，反而安静得近乎诡异。","林静姝坐在主控台前，手边放着一束蔚蓝之海。"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第五幕","text":["那是她记忆里曾经属于旧日故乡的花。","花瓣脆弱，颜色浅淡，仿佛随时会在宇宙风暴中凋零。","她低头修剪枝叶，外界震耳欲聋的炮火声仿佛与她无关。","通讯频道里不断传来战报。","“第七舰队防线突破。”","“改造军团已进入第二跃迁节点。”"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第五幕","text":["“芯片同步率保持百分之九十八以上。”","林静姝只是轻轻应了一声。","“继续。”","她看着手中的花，声音很轻。","“如果人类永远无法摆脱痛苦，那就替他们拿走痛苦。”","“这有什么错。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第五幕","text":["【白银军舰】","另一端。","白银十卫舰队排列成锋利阵型，像一把刺入黑暗的银色长刃。","泊松杨、图兰、金等白银十卫成员分别镇守各处跃迁节点。","湛卢人形站在指挥台旁，碧绿色光学眼不断刷新战场数据。","“先生，敌方改造单位数量持续增加。”"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第五幕","text":["“当前战场环境下，普通精神防御系统无法抵御芯片干扰。”","“建议优先破坏中央控制节点。”","林静恒站在主控台前。","他没有看那些不断跳动的伤亡数字，而是盯着敌方舰队后方那些被芯片控制的驾驶员编号。","那些编号后面，曾经都是活生生的人。","普通士兵。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第五幕","text":["年轻驾驶员。","甚至还有被强行改造的平民。","湛卢停顿片刻。","“先生。”","“根据历史数据分析，您当前决策压力指数超过正常范围。”","林静恒淡淡道："],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第五幕","text":["“湛卢。”","“是。”","“他们不是数据。”","湛卢沉默两秒。","“确认。”","“重新调整攻击策略。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第五幕","text":["“优先解除芯片控制，降低人员伤亡。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第五幕","text":["【玩家战场选择】","选择一：【白银突破核心舰队】","路线归属：白银守护线","触发剧情：","玩家跟随林静恒进入主战区域。","林静恒亲自制定跃迁封锁方案。","他没有第一时间下达歼灭命令，而是在星图上划出数条撤离路线。","湛卢询问：","“先生，按照传统军事方案，优先摧毁敌方主力舰队，可提高胜率。”","林静恒看着那些撤离航线。","“战争不是为了证明谁更擅长毁灭。”","“先救人。”","“再结束战争。”","获得线索：","白银要塞遗留屏蔽武器档案","改造芯片物理破解方案","林静恒隐藏军事档案","羁绊变化：","林静恒信任度提升。","白银十卫认可度提升。","解锁：","【白银孤刃】","选择二：【寻找芯片破解节点】","路线归属：星海火种线","触发剧情：","银河城实验室内。","陆必行带领空脑症学生破解芯片底层代码。","空脑症天然隔绝伊甸园精神信号，成为整个战争中唯一不受芯片影响的人群。","实验室里，少年们第一次成为拯救星系的关键力量。","“他们一直认为我们是不完整的人。”","“可偏偏是这些所谓的不完整，救了所有人。”","湛卢同步传输数据。","“检测完成。”","“空脑精神屏障可有效隔离芯片控制信号。”","“建议建立全域保护网络。”","获得线索：","女娲计划原始档案","空脑精神屏障理论","芯片核心漏洞","羁绊变化：","陆必行信任度提升。","解锁：","【星海星火】"],"choices":[{"title":"白银突破核心舰队","key":"route_145_0"},{"title":"寻找芯片破解节点","key":"route_145_1"}],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第六幕","text":["第六幕","【林静姝通讯接入】","战场中央。","林静姝突然接入全域通讯。","她的声音没有愤怒，也没有胜利后的狂热。","只是平静。"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第六幕","text":["像是在陈述一个早已确定的答案。","“哥哥。”","“你真的认为，人类可以靠自己走下去吗？”","林静恒没有回答。","林静姝继续说道：","“他们会恐惧，会贪婪，会战争，会互相伤害。”"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第六幕","text":["“他们需要一个更高层次的管理者。”","“需要有人替他们选择。”","巨大的虫洞光芒映照在林静恒眼中。","他终于开口：","“所以你认为。”","“夺走选择权，是保护。”"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第六幕","text":["林静姝轻声道：","“至少比让他们继续痛苦好。”","林静恒沉默片刻。","“你错了。”","“人活着，不是为了避免所有痛苦。”","“而是有资格决定自己承受什么。”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第六幕","text":["【关键主线选择】","选择A：【接受均衡秩序】","路线解锁：机械均衡线","玩家认可伍尔夫方案。","以最高效率结束战争。","代价：","人类获得稳定，却逐渐失去自主。","星海学院受到联盟统一管理。","空脑症仍被视为特殊风险群体。","选择B：【守护自主选择】","路线解锁：星火传承线","玩家拒绝所有强制控制方案。","联合白银十卫、空脑军团以及第八星系力量。","目标：","不是创造完美世界。","而是守住每个人选择人生的权利。"],"choices":[{"title":"接受均衡秩序","key":"route_150_0"},{"title":"守护自主选择","key":"route_150_1"}],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第七幕","text":["第七幕","【玫瑰之心虫洞核心区域】","战争持续了整整三十七小时。","虫洞外围漂浮着无数舰船残骸，能源光束逐渐熄灭，只剩下破碎的警报声在深空中回荡。","曾经象征星际交通与文明连接的玫瑰之心，此刻成为决定八大星系未来方向的战场。","三条道路，在这一刻交汇。"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第七幕","text":["【路线一：白银守护】","解锁条件：","全程选择【白银锋刃】路线；","未完成双线羁绊；","未收集完整芯片破解资料。","【白银军舰】"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第七幕","text":["林静恒站在指挥台前。","星图上，林静姝主舰的位置不断闪烁。","湛卢低声汇报：","“先生，敌方核心能源节点已暴露。”","“当前攻击成功率：86.9%。”","“预计造成不可逆损毁。”"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第七幕","text":["林静恒沉默片刻。","他知道。","这一击之后，造神芯片体系会彻底崩塌。","也意味着无数被卷入战争的人，将无法再回头。","湛卢看向他。","“先生。”"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第七幕","text":["“是否执行最终攻击？”","林静恒望着那些红色标记。","许久。","他说：","“执行。”","白银十卫突破最后防线。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第七幕","text":["湛卢机甲化作一道银色流光，穿过虫洞乱流。","林静姝看着他，轻声问：","“哥哥。”","“你还是选择他们。”","林静恒没有回答。","只是看着她。"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第七幕","text":["那个曾经跟在自己身后的妹妹。","那个曾经也相信世界会变好的人。","林静姝笑了一下。","很轻。","后来，","战争结束。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第七幕","text":["造神芯片生产链被摧毁。","结局评价：","【白银守护】","你选择成为一把刀。","不是因为喜欢杀戮。","而是因为总要有人握住刀柄，替后来的人挡住黑暗。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第七幕","text":["核心关键词：","孤刃、责任、牺牲、遥遥守望。","【路线二：新星海时代】","解锁条件：","全程选择【溯源芯片】路线；","未完成白银战场全部线索；"],"choices":[],"background":"背景图片/指挥舰驾驶舱-太空战斗场景.png"},{"chapter":"第七幕","text":["未触发隐藏双线结局。","【银河城·星海学院】","战争最后阶段。","陆必行没有选择摧毁所有芯片。","而是选择破解。","他知道。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"第七幕","text":["技术本身没有善恶。","真正危险的是那些试图利用技术替所有人决定未来的人。","实验室里。","无数空脑学生围绕主控屏幕。","年轻的学生紧张地看着数据。","“校长，如果失败……”"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第七幕","text":["陆必行笑了一下。","还是那个熟悉的、总喜欢给别人希望的人。","“失败也没关系。”","“人类又不是第一次失败。”","“重要的是，我们失败之后，还有重新选择的机会。”","芯片控制网络逐渐瓦解。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第七幕","text":["伊甸园精神干预系统被重新限制。","八大星系重新建立自治协议。","星海学院成为新的文明核心。","这里不再区分：","正常人。","空脑症。"],"choices":[],"background":"背景图片/星海学院场景.png"},{"chapter":"第七幕","text":["残次品。","所有孩子都可以拥有属于自己的未来。","结局评价：","【新星海时代】","你没有选择成为最锋利的武器。","你选择守住一颗星球，一群孩子，以及人类仍然可以犯错的未来。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第七幕","text":["核心关键词：","文明、包容、教育、星火传承。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"隐藏终极结局","text":["【隐藏终极结局】","玫瑰之心共生","解锁条件：","必须同时满足：","◆ 第五章解锁：","【十六年星火】"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"隐藏终极结局","text":["【十六年孤刃】","双羁绊。","◆ 第六章完成：","【白银锋刃】","与","【溯源芯片】"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"隐藏终极结局","text":["双路线。","◆ 主线选择：","【死守人类自主选择权】","◆ 收集：","林静姝完整档案；","伍尔夫元帅理念档案；"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"隐藏终极结局","text":["哈登博士实验记录。","【银河城最高观景台】","数日后。","清晨。","银河城灯火铺满地表。","远处，玫瑰之心虫洞安静悬浮。"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"隐藏终极结局","text":["没有战争。","没有警报。","只有漫长之后终于归来的平静。","林静恒站在那里。","身上的白银战甲仍带着战争留下的划痕。","陆必行站在他身旁。"],"choices":[],"background":"背景图片/军事要塞白银要塞-战争场景.png"},{"chapter":"隐藏终极结局","text":["两个人都没有说话。","十六年。","无数次错过。","无数次擦肩。","最终都停在了这里。","湛卢安静记录。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"隐藏终极结局","text":["【检测结果：】","【统帅情绪稳定。】","【长期压力指数下降。】"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"建议保存该历史节点。","text":["【建议保存该历史节点。】","两个人并肩站在银河城最高处。","看着这片曾经被称作荒漠的土地。","一点一点。","长出文明。"],"choices":[],"background":"背景图片/废弃星球荒芜城市-凯莱星场景.png"},{"chapter":"第七章终章","text":["第七章终章","玫瑰之心的硝烟终会散去。","战争留下的伤痕不会立即消失。","但废墟之上，总会有人重新种下种子。","有人选择成为利刃。","替众生挡住黑暗。"],"choices":[],"background":"背景图片/玫瑰之心虫洞-最终决战.png"},{"chapter":"第七章终章","text":["有人选择成为灯火。","替后来者守住方向。","人类从来不会因为完美而伟大。","真正珍贵的，是明知自己会犯错。","依旧愿意选择。","愿意爱。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"第七章终章","text":["愿意承担。","愿意在漫长宇宙中，寻找属于自己的道路。"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"主线通关","text":["【主线通关】","获得永久称号：","「星海守望者」","官方评价：","你没有创造一个没有痛苦的世界。","你守住的是——"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"},{"chapter":"主线通关","text":["即使身处黑暗，人类依然拥有选择未来的权利。","《第八星系风云》","陆必行主线剧情·完"],"choices":[],"background":"背景图片/星空背景-标题画面+通用背景.png"}]}],"backgrounds":["背景图片/星空背景-标题画面+通用背景.png","背景图片/沃托白塔-政治场景.png","背景图片/星海学院场景.png","背景图片/指挥舰驾驶舱-太空战斗场景.png","背景图片/废弃星球荒芜城市-凯莱星场景.png","背景图片/军事要塞白银要塞-战争场景.png","背景图片/玫瑰之心虫洞-最终决战.png"]};
